// Read CV replaces the item's JSON with file metadata, so the job comes from the loop itself.
const base = $('Send Loop1').first().json;
const res = $input.first().json || {};
// Graph returns {success:true}; SMTP returned messageId/accepted. Accept either.
const sendOk = res.success === true || !!res.messageId
  || (Array.isArray(res.accepted) && res.accepted.length > 0);
const err = res.error ? (res.error.message || res.error.description || JSON.stringify(res.error)) : '';
return [{ json: { ...base, sendAttempted: true, sendOk,
  sendError: sendOk ? '' : String(err || 'no confirmation from the mail API').slice(0, 300) } }];

const cfg = $('Config1').first().json;
// Spacing between mails, not a delay before each one: the first goes immediately, each later
// one waits a random lo..hi seconds after the previous. The old per-mail wait of up to
// 25-40 MINUTES made a 3-mail run take over an hour. Under 65 s n8n also holds the wait in
// memory instead of parking the whole execution in the database and resuming it.
const lo = Math.max(0, Number(cfg.sendGapMinSeconds ?? 20));
const hi = Math.max(lo, Number(cfg.sendGapMaxSeconds ?? 55));
return $input.all().map((item, i) => ({ json: { ...item.json,
  gapSeconds: i === 0 ? 0 : Math.round(lo + Math.random() * (hi - lo)) } }));

const cfg = $('Config1').first().json;
// Outcomes come from Record, not $input: this node's input is the Postgres INSERT result,
// {success:true} per row, which carries none of the target fields.
const items = $('Record').all().map(i => i.json).filter(j => !j.noCandidates);
const saveErrors = $input.all().filter(i => i.json && i.json.error).length;
const failed = items.filter(i => i.status === 'send_failed');
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const scanned = $('Target Pages').all().length;
const withAddr = $('Extract Published Email').all().length;
const sent = items.filter(i => i.status === 'sent');

const card = j => `<div style="border:1px solid #e2e2e2;border-radius:8px;padding:14px;margin:0 0 14px;">
  <div style="font-size:16px;font-weight:600;">${esc(j.name)}</div>
  <div style="color:#555;">${esc(j.contactEmail)} <span style="background:#eef;border-radius:3px;
    padding:1px 5px;font-size:12px;">${esc(j.tier)}</span> &middot; found on
    <a href="${esc(j.foundOn)}">${esc(j.foundOn)}</a> &middot; ${esc(j.lang)}</div>
  ${j.sendError ? '<div style="color:#a00;font-size:13px;margin:6px 0;"><b>Send failed:</b> '
    + esc(j.sendError) + '</div>' : ''}
  ${j.letter ? '<details><summary style="cursor:pointer;color:#0b57d0;">Outreach mail</summary>'
    + '<pre style="white-space:pre-wrap;font:13px/1.5 -apple-system,Segoe UI,sans-serif;'
    + 'background:#fafafa;padding:10px;border-radius:6px;">' + esc(j.letter) + '</pre></details>' : ''}
</div>`;

const banner = cfg.dryRun ? '<div style="background:#fff4d6;border:1px solid #e8c766;padding:10px;'
  + 'border-radius:6px;margin-bottom:16px;"><b>DRY RUN</b> - nothing sent.</div>' : '';

return [{ json: {
  subject: '[Speculative] ' + items.length + ' contacted - ' + new Date().toISOString().slice(0, 10),
  html: `<div style="font:14px/1.6 -apple-system,Segoe UI,Roboto,sans-serif;max-width:720px;margin:auto;">
    <h2 style="margin:0 0 4px;">Speculative outreach</h2>
    <p style="color:#666;">${scanned} pages checked &middot; ${withAddr} published careers addresses found
      &middot; ${items.length} approached &middot; ${sent.length} sent${failed.length
      ? ' &middot; <b style="color:#a00;">' + failed.length + ' failed to send</b>' : ''}${saveErrors
      ? ' &middot; <b style="color:#a00;">' + saveErrors + ' not saved to history</b>' : ''}</p>
    ${banner}${items.map(card).join('')}
    <p style="color:#888;font-size:12px;">Only addresses published on the company's own pages are used.
      Guessed patterns are never mailed - bounces would damage the sender reputation the daily
      pipeline depends on.</p></div>` } }];

const cfg = $('Config1').first().json;
// Every target arrives once: from the send loop, from the "not sent" branch, or as the
// "nothing new" sentinel. Only 'sent' suppresses a company on later runs (Load Contacted).
const statusOf = j => {
  if (j.sendAttempted) return j.sendOk ? 'sent' : 'send_failed';
  if (!j.llmOk) return 'letter_failed';
  return cfg.dryRun ? 'dry_run' : 'queued';
};
const out = [];
for (const { json: j } of $input.all()) {
  if (j.noCandidates) continue;
  const status = statusOf(j);
  out.push({ json: { ...j, status, row: {
    dedupe_key: j.dedupeKey, source: 'speculative', company: j.name,
    title: 'Initiativbewerbung - AI Engineer', city: null, country: null,
    region: (j.regions || []).join(','), url: j.foundOn || null,
    contact_email: j.contactEmail || null, fit: null,
    score_reason: j.sendError ? 'send failed: ' + j.sendError : null,
    lang: j.lang || null, letter: j.letter || null, channel: 'speculative', status
  } } });
}
if (!out.length) return [{ json: { noCandidates: true, status: 'none', row: {} } }];
return out;

// Index-aligned with the HTTP node's output: one response per request, in order.
const jobs = $('Build Outreach Prompt').all();

const parse = txt => {
  try { return JSON.parse(txt); } catch (e) {
    // Models sometimes wrap the JSON in fences or add a stray brace ('{"{"fit":35,...}').
    // Try each '{' as a start against the last few '}' and keep the first object that parses.
    const s = String(txt || '').replace(/```(?:json)?/gi, '');
    const ends = [];
    for (let k = s.lastIndexOf('}'); k !== -1 && ends.length < 5; k = s.lastIndexOf('}', k - 1)) ends.push(k);
    for (let i = s.indexOf('{'); i !== -1; i = s.indexOf('{', i + 1)) {
      for (const k of ends) {
        if (k <= i) continue;
        try { const o = JSON.parse(s.slice(i, k + 1)); if (o && typeof o === 'object') return o; } catch (e2) {}
      }
    }
  }
  return {};
};

return $input.all().map((item, i) => {
  const base = { ...((jobs[i] || {}).json || {}) };
  delete base.llmPayload;
  const res = item.json || {};
  let txt = ''; try { txt = res.choices[0].message.content || ''; } catch (e) {}
  const p = parse(txt);
  const letter = String(p.body || '').trim();
  return { json: { ...base, letter, llmOk: letter.length > 120,
    subject: String(p.subject || ('Initiativbewerbung - ' + base.name)).slice(0, 180) } };
});

// One board response per target, in order (fetched as text, so a Lever array can't split into
// several items and shift the rest). board[i] belongs to the i-th target.
const targets = $('Has Targets?').all(0);

// Which disciplines are growing, and which tech recurs in their own ad titles.
const DISC = {
  'ML/AI': /\b(ml|machine learning|ai|llm|nlp|computer vision|data scien|research)\b/i,
  'backend/platform': /\b(backend|platform|infrastructure|sre|devops|cloud)\b/i,
  'data': /\b(data engineer|analytics|data platform)\b/i,
  'frontend': /\b(frontend|front-end|web|react)\b/i,
  'security': /\b(security|iam|compliance)\b/i
};
// Only engineering titles are useful context - their accounting and sales ads are noise here.
const ENGT = /\b(engineer|engineering|developer|scientist|research|architect|ml|ai|llm|data|platform|infrastructure|backend|devops|sre)\b/i;
const NOISE = /\b(account executive|accountant|accounts payable|sales|marketing|recruiter|support specialist|office|legal|finance|payroll)\b/i;
const TECH = /\b(python|golang|rust|java|kotlin|typescript|react|kubernetes|aws|azure|gcp|spark|kafka|pytorch|tensorflow|llm|rag)\b/gi;

return $input.all().map((item, i) => {
  const base = (targets[i] || {}).json || {};
  let d = item.json || {};
  if (typeof d.data === 'string') { try { d = JSON.parse(d.data); } catch (e) { d = {}; } }

  let titles = [];
  if (Array.isArray(d.jobs)) titles = d.jobs.map(j => j.title || '');
  else if (Array.isArray(d)) titles = d.map(j => j.text || '');
  titles = titles.filter(Boolean);

  const disciplines = Object.entries(DISC)
    .map(([k, rx]) => [k, titles.filter(t => rx.test(t)).length])
    .filter(([, n]) => n > 0).sort((a, b) => b[1] - a[1]);
  const engTitles = titles.filter(t => ENGT.test(t) && !NOISE.test(t));
  const tech = [...new Set((titles.join(' ').match(TECH) || []).map(t => t.toLowerCase()))].slice(0, 8);

  const brief = [
    'Open roles on their board: ' + titles.length + ', of which ' + engTitles.length + ' engineering.',
    disciplines.length ? 'Hiring concentrated in: '
      + disciplines.slice(0, 3).map(([k, n]) => k + ' (' + n + ')').join(', ') + '.' : '',
    tech.length ? 'Tech recurring in their own ad titles: ' + tech.join(', ') + '.' : '',
    engTitles.length ? 'Relevant current openings: ' + engTitles.slice(0, 6).join('; ') + '.' : '',
    base.profileText ? 'How they describe themselves: ' + base.profileText : ''
  ].filter(Boolean).join(' ');

  return { json: { ...base, openRoles: titles.length, engRoles: engTitles.length,
    disciplines: disciplines.map(([k]) => k), companyBrief: brief } };
});

const cfg = $('Config1').first().json;
const seen = new Set($('Load Contacted').all()
  .map(r => String((r.json || {}).company || '').toLowerCase()).filter(Boolean));
const out = [];
for (const item of $('Extract Published Email').all()) {
  const j = item.json;
  if (seen.has(String(j.name).toLowerCase())) continue;   // already applied to a real role there
  out.push({ json: { ...j, dedupeKey: String(j.name).toLowerCase().replace(/[^a-z0-9]+/g, '') + '|speculative' } });
  if (out.length >= (cfg.maxPerRun || 5)) break;
}
// Never return nothing - the digest must still go out on a quiet run.
return out.length ? out : [{ json: { noCandidates: true } }];

parameters.query:
SELECT lower(company) AS company FROM job_applications
WHERE applied_at > now() - make_interval(days => $1)
  AND status = 'sent';

