// One item per (company x candidate path). A 404 is harmless - it simply yields no address.
const PATHS = ['/karriere', '/careers', '/jobs', '/impressum', '/contact'];
const out = [];
for (const t of TARGETS) {
  for (const p of PATHS) {
    out.push({ json: { ...t, url: 'https://' + t.domain + p } });
