const cfg = $('Config').first().json;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const day = new Date().toISOString().slice(0, 10);

// Outcomes come from Record Outcome, not $input: this node's input is the Postgres INSERT
// result - {success:true} per row, none of the job fields. Reading $input here is what made
// earlier digests report "0 sent" with blank cards after mails had actually gone out.
const items = $('Record Outcome').all().map(i => i.json).filter(j => !j.noCandidates);
const tryAll = n => { try { return $(n).all(); } catch (e) { return []; } };   // node may not have run
const saveErrors = tryAll('Save Application').filter(i => i.json && i.json.error).length;
// The spreadsheet (one file, rebuilt each run). Write Export's output is this node's input.
const exportErr = (($input.all()[0] || {}).json || {}).error;
const exportRows = tryAll('Build Export').filter(i => i.json && i.json.Link).length;
const exportNew = tryAll('Build Export').filter(i => i.json && i.json.New).length;
const by = (...s) => items.filter(i => s.includes(i.status));
const sent = by('sent'), failed = by('send_failed'), queued = by('manual', 'queued', 'dry_run');
const letterFailed = by('letter_failed'), deferred = by('deferred');
const dropped = by('rejected_fit'), scoreFailed = by('score_failed');

// Count sources at intake, not in the shortlist: the shortlist is ~8 roles and routinely
