const ran = f => { try { return f(); } catch (e) { return []; } };   // node may not have run
const hunt = ((ran(() => $('Email Hunt').all())[0] || {}).json || {}).huntStats;
const plan = ((ran(() => $('Plan Run').all())[0] || {}).json) || {};
const didFetch = plan.fetch !== false;
const fetched = {};
for (const i of ran(() => $('Merge Sources').all())) {
  const s = String(i.json.source || '').split(':')[0];
  if (s) fetched[s] = (fetched[s] || 0) + 1;
}
const relevant = ran(() => $('Filter Relevant').all()).filter(i => i.json && i.json.title && !i.json.emailReserve).length;
const expected = ['ats'];
// The German sources only run for German regions; with Amsterdam alone they are off on purpose.
if ((cfg.regions || []).some(r => r !== 'amsterdam')) expected.push('bundesagentur', 'arbeitnow');
if (cfg.useAdzuna && (cfg.regions || []).includes('amsterdam')) expected.push('adzuna');
if (cfg.useWorkable && (cfg.regions || []).length) expected.push('workable');
if (cfg.useEnglishJobs && (cfg.regions || []).includes('amsterdam')) expected.push('englishjobs');
if (cfg.useJobicy && (cfg.regions || []).includes('remote')) expected.push('jobicy');
if (cfg.useBundJobs && (cfg.regions || []).some(r => r === 'bayern' || r === 'berlin')) expected.push('bund');
if (cfg.useInstaffo && (cfg.regions || []).some(r => r === 'berlin' || r === 'bayern')) expected.push('instaffo');
const silent = didFetch ? expected.filter(s => !fetched[s]) : [];
// Career feeds that errored: a watchlist employer switched systems, a board was renamed, ...
// (a fetch node that had nothing to do never ran, and referencing it would throw)
const safe = f => { try { return f(); } catch (e) { return []; } };
const failedOf = (fetchNode, branch) => {
  const metas = safe(() => $('Is POST?').all(branch));
  return safe(() => $(fetchNode).all())
    .map((f, i) => (f.json && f.json.error) ? ((metas[i] || {}).json || {}).name : null);
};
const failedFeeds = [...new Set(failedOf('Fetch Workday', 0).concat(failedOf('Fetch ATS Board', 1)).filter(Boolean))];

const box = (bg, border, html) => `<div style="background:${bg};border:1px solid ${border};`
  + `padding:10px;border-radius:6px;margin-bottom:16px;">${html}</div>`;
const alerts = [
  silent.length ? box('#ffe8e8', '#e88', '<b>Source returned nothing:</b> ' + esc(silent.join(', '))
    + ' - check whether the API changed.') : '',
  saveErrors ? box('#ffe8e8', '#e88', '<b>' + saveErrors + ' history row(s) failed to save.</b> '
    + 'Those companies are not suppressed and may be contacted again - check Postgres.') : '',
  failed.length ? box('#ffe8e8', '#e88', '<b>' + failed.length + ' mail(s) failed to send.</b> '
    + 'Letters are below - send them by hand or fix the Outlook credential.') : '',
  failedFeeds.length ? box('#fff4d6', '#e8c766', '<b>Career feeds that failed:</b> ' + esc(failedFeeds.join(', '))
    + ' - check their row in the <code>employers</code> table.') : ''
].join('');
const planNote = didFetch ? '' : box('#eef6ee', '#9c9', '<b>No fetching this run:</b> '
  + esc(plan.backlog) + ' unsent jobs with an email address were already in the database (limit '
  + esc(plan.target) + ').');
const banner = planNote + (cfg.dryRun ? box('#fff4d6', '#e8c766', '<b>DRY RUN</b> - nothing sent. Set '
  + '<code>dryRun</code> to false in Config to arm.') : '');

const card = j => `
  <div style="border:1px solid #e2e2e2;border-radius:8px;padding:14px;margin:0 0 14px;">
    <div style="font-size:16px;font-weight:600;">${esc(j.title)}</div>
    <div style="color:#555;">${esc(j.company)} &middot; ${esc(j.city)}
      &middot; fit <b>${esc(j.fit)}</b>${j.homeoffice ? ' &middot; remote/hybrid' : ''}
      &middot; <span style="color:#888;">${esc(j.source)}</span></div>
    ${j.sendError ? '<div style="color:#a00;font-size:13px;margin:4px 0;"><b>Send failed:</b> '
      + esc(j.sendError) + '</div>' : ''}
    <div style="color:#777;font-size:13px;margin:4px 0;">${esc(j.scoreReason)}</div>
    ${(j.missing || []).length ? '<div style="color:#a33;font-size:12px;">gaps: '
      + esc((j.missing || []).join(', ')) + '</div>' : ''}
    <div style="margin:6px 0;"><a href="${esc(j.url)}">Open &amp; apply &rarr;</a>
      ${j.contactEmail ? ' &middot; <a href="mailto:' + esc(j.contactEmail) + '">' + esc(j.contactEmail) + '</a>'
        : j.publishedEmail ? ' &middot; <a href="mailto:' + esc(j.publishedEmail) + '">' + esc(j.publishedEmail)
          + '</a> <span style="color:#888;">(fit under the auto-send bar - your call)</span>' : ''}</div>
    ${j.angle ? '<div style="margin:6px 0;padding:8px 10px;background:#f2f7ff;border-left:3px solid #0b57d0;'
      + 'border-radius:4px;font-size:13px;"><b>Angle:</b> ' + esc(j.angle) + '</div>' : ''}
    ${(j.talkingPoints || []).length ? '<div style="font-size:13px;margin:6px 0;"><b>Your evidence</b>'
      + '<ul style="margin:4px 0 0;padding-left:18px;">'
      + j.talkingPoints.map(t => '<li>' + esc(t) + '</li>').join('') + '</ul></div>' : ''}
    ${j.linkedinNote ? '<details><summary style="cursor:pointer;color:#0a66c2;">LinkedIn note ('
      + esc(j.linkedinNote.length) + '/300) - send this yourself</summary><pre style="white-space:pre-wrap;'
      + 'font:13px/1.5 -apple-system,Segoe UI,sans-serif;background:#f3f8fd;padding:10px;'
      + 'border-radius:6px;border:1px solid #cfe2f5;">' + esc(j.linkedinNote) + '</pre>'
      + '<div style="font-size:12px;color:#777;padding:0 2px 8px;">Find whoever leads engineering '
      + 'or AI at ' + esc(j.company) + ' on LinkedIn and send this by hand. Not automated - '
      + 'person-to-person is the point.</div></details>' : ''}
    ${j.letter ? '<details><summary style="cursor:pointer;color:#0b57d0;">Cover letter ('
      + esc(j.lang) + ') - copy &amp; paste</summary><pre style="white-space:pre-wrap;'
      + 'font:13px/1.5 -apple-system,Segoe UI,sans-serif;background:#fafafa;padding:10px;'
      + 'border-radius:6px;">' + esc(j.letter) + '</pre></details>' : ''}
  </div>`;

const list = (title, rows, fmt) => rows.length
  ? '<h3 style="color:#888;">' + title + '</h3><ul style="color:#888;font-size:13px;">'
    + rows.map(j => '<li>' + fmt(j) + '</li>').join('') + '</ul>' : '';

const empty = items.length ? '' : '<p>No new candidates today. ' + relevant + ' relevant roles '
  + 'were found, but every company is already approached or its roles were already rejected. '
  + 'Widen <code>regions</code>/<code>keywords</code> or lower <code>minRelevance</code> for more.</p>';

const html = `<div style="font:14px/1.6 -apple-system,Segoe UI,Roboto,sans-serif;max-width:760px;margin:auto;color:#111;">
  <h2 style="margin:0 0 4px;">Job run - ${day}</h2>
  <p style="color:#666;margin:0 0 16px;">${relevant} relevant &middot; ${items.length} scored
    &middot; ${sent.length} emailed &middot; ${queued.length} ready to apply
    &middot; ${dropped.length} below fit threshold</p>
  ${alerts}${banner}${empty}
  ${hunt ? '<p style="color:#555;font-size:13px;margin:0 0 12px;"><b>Email search:</b> target ' + esc(hunt.target)
    + ' &middot; ' + esc(hunt.inPool) + ' in the pool &middot; checked ' + esc(hunt.checked) + ' more ads &middot; found '
    + esc(hunt.found) + (hunt.inPool + hunt.found < hunt.target ? ' &middot; <b>no more candidates</b>'
    + ' - lower minRelevanceEmail or widen keywords for more' : '') + (hunt.failed ? ' &middot; ' + esc(hunt.failed) + ' fetch errors' : '') + '</p>' : ''}
  <p style="color:#555;font-size:13px;margin:0 0 12px;"><b>Apply-yourself list:</b> ${exportErr
    ? '<span style="color:#a00;">not written (' + esc(String(exportErr.message || exportErr).slice(0, 160)) + ') - close it in Excel, or restart n8n with start-n8n.ps1</span>'
    : esc(exportRows) + ' open jobs (' + esc(exportNew) + ' new) in ' + esc(cfg.exportDir) + '/apply-yourself.xlsx'}</p>
  ${sent.length ? '<h3>Emailed automatically</h3>' + sent.map(card).join('') : ''}
  ${failed.length ? '<h3 style="color:#a00;">Send failed - apply by hand</h3>' + failed.map(card).join('') : ''}
  ${queued.length ? '<h3>Apply yourself (no email address) - saved to your manual list</h3>' + queued.map(card).join('') : ''}
  ${list('Passed fit, held for a later run (cap is ' + esc(cfg.maxPerRun || 8) + ' letters/run)', deferred,
    j => esc(j.title) + ' - ' + esc(j.company) + ' (fit ' + esc(j.fit) + ')')}
  ${list('Letter generation failed - retried next run', letterFailed,
    j => esc(j.title) + ' - ' + esc(j.company) + ': ' + esc(j.letterError))}
  ${list('Scoring failed - retried next run', scoreFailed,
    j => esc(j.title) + ' - ' + esc(j.company) + ': ' + esc(j.scoreError))}
  ${list('Below threshold', dropped,
    j => esc(j.title) + ' - ' + esc(j.company) + ' (fit ' + esc(j.fit) + ')')}
  <p style="color:#888;font-size:12px;">fetched by source: ${esc(JSON.stringify(fetched))}</p>
</div>`;

const flag = (silent.length || saveErrors || failed.length) ? '[Jobs][CHECK] ' : '[Jobs] ';
return [{ json: { subject: flag + `${sent.length} emailed, ${queued.length} to apply - ` + day, html } }];

// Layer 3 feed: every employer behind a RELEVANT search-source ad (Bundesagentur, Adzuna,
// Arbeitnow) becomes a discovery candidate. The Employer Discovery workflow later tries to find
// its own careers feed; if it does, the company joins the `employers` watchlist.
const norm = s => String(s || '').toLowerCase().replace(/ß/g, 'ss')
  .normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim();
const LEGAL = /\b(gmbh|mbh|ag|se|kg|kgaa|co|ug|ohg|e v|ev|b v|bv|n v|nv|inc|llc|ltd|limited|plc|corp|corporation|sa|sas|sarl|srl|spa|holding|group|gruppe|deutschland|germany|netherlands|nederland|europe)\b/g;
const coKey = s => norm(s).replace(LEGAL, ' ').replace(/\s+/g, ' ').trim() || norm(s);
// Staffing agencies post for unnamed clients - their own careers site is not where the job is.
const AGENCY = /personal|recruit|zeitarbeit|staffing|arbeitnehmer|hays|randstad|manpower|adecco|gulp|solcom|etengo|computer futures|experis|brunel|ferchau|amadeus fire|\bdis ag\b|jobs?\b/i;

const rows = new Map();
for (const { json: j } of $input.all()) {
  if (!j || !j.company || j.tier !== 'search' || j.isAgency || AGENCY.test(j.company)) continue;
  const k = coKey(j.company);
  if (!k) continue;
  // ads = relevant ads this run: a rough size signal, so discovery can try smaller companies first
  const r = rows.get(k) || { name: String(j.company).trim(), norm_name: k, regions: [], sources: [], ads: 0 };
  r.ads++;
  if (j.region && !r.regions.includes(j.region)) r.regions.push(j.region);
  if (j.source && !r.sources.includes(j.source)) r.sources.push(j.source);
  rows.set(k, r);
}
return rows.size ? [{ json: { rows: [...rows.values()] } }] : [];

const cfg = $('Config').first().json;

// Every job arrives here exactly once, from one of four places: the fit gate, the manual
// queue, the send loop, or the "nothing to do today" sentinel.
// Suppression (Load History): sent / queued / send_failed block the company, rejected_fit
// blocks the role. score_failed, letter_failed and deferred block nothing - retried next run.
const statusOf = j => {
  if (j.stage === 'score_failed') return 'score_failed';
  if (j.stage === 'rejected_fit') return 'rejected_fit';
  if (j.stage === 'deferred') return 'deferred';
  if (j.stage === 'manual') return cfg.dryRun ? 'dry_run' : 'manual';
  if (j.sendAttempted) return j.sendOk ? 'sent' : 'send_failed';
  if (!j.llmOk) return 'letter_failed';
  return cfg.dryRun ? 'dry_run' : 'manual';   // no address to email: goes on the apply-yourself list
};

const out = [];
for (const { json: j } of $input.all()) {
  if (j.noCandidates) continue;
  const status = statusOf(j);
  out.push({ json: { ...j, status, row: {
    dedupe_key: j.dedupeKey, source: j.source, company: j.company, title: j.title,
    city: j.city, country: j.country, region: j.region, url: j.url,
    contact_email: j.contactEmail || j.publishedEmail || null, fit: j.fit ?? null,
    score_reason: j.scoreReason || j.scoreError || j.letterError || j.sendError || null,
    lang: j.lang || null, letter: j.letter || null, channel: j.applyChannel || null, status
  } } });
}
// Keep one item flowing so Save and the digest still run on an empty day. Its row has no
// dedupe_key, and the INSERT's WHERE clause skips it.
if (!out.length) return [{ json: { noCandidates: true, status: 'none', row: {} } }];
return out;

// Index-aligned with the HTTP node's output: one response per request, in order.
const jobs = $('Build Letter Prompt').all();

const parse = txt => {
  try { return JSON.parse(txt); } catch (e) {
    // Models sometimes wrap the JSON in fences or add a stray brace ('{"{"fit":35,...}').
    // Try each '{' as a start against the last few '}' and keep the first object that parses.
    const s = String(txt || '').replace(/```(?:json)?/gi, '');
    const ends = [];
    for (let k = s.lastIndexOf('}'); k !== -1 && ends.length < 5; k = s.lastIndexOf('}', k - 1)) ends.push(k);
    for (let i = s.indexOf('{'); i !== -1; i = s.indexOf('{', i + 1)) {
      for (const k of ends) {
        if (k <= i) continue;
        try { const o = JSON.parse(s.slice(i, k + 1)); if (o && typeof o === 'object') return o; } catch (e2) {}
      }
    }
  }
  return {};
};

return $input.all().map((item, i) => {
  const base = { ...((jobs[i] || {}).json || {}) };
  delete base.llmPayload;
  const res = item.json || {};
  let txt = ''; try { txt = res.choices[0].message.content || ''; } catch (e) {}
  const p = parse(txt);
  const letter = String(p.body || '').trim();
  let note = String(p.linkedinNote || '').trim();
  // LinkedIn connection requests hard-cap at 300 chars; truncate on a word boundary.
  if (note.length > 300) note = note.slice(0, 297).replace(/\s+\S*$/, '') + '...';
  const llmOk = letter.length > 80;
  return { json: { ...base, letter,
    subject: String(p.subject || ('Application: ' + base.title)).slice(0, 180),
    talkingPoints: Array.isArray(p.talkingPoints) ? p.talkingPoints.slice(0, 3).map(String) : [],
    linkedinNote: note,
    angle: String(p.angle || ''),
    letterError: llmOk ? '' : String(res.error ? (res.error.message || JSON.stringify(res.error))
                                                 : 'empty or unparseable letter').slice(0, 200),
    llmOk } };
});

const cfg = $('Config').first().json;
const min = cfg.minFitScore ?? 70;
// Index-aligned with the HTTP node's output: one response per request, in order.
const jobs = $('Build Score Prompt').all();

const parse = txt => {
  try { return JSON.parse(txt); } catch (e) {
    // Models sometimes wrap the JSON in fences or add a stray brace ('{"{"fit":35,...}').
    // Try each '{' as a start against the last few '}' and keep the first object that parses.
    const s = String(txt || '').replace(/```(?:json)?/gi, '');
    const ends = [];
    for (let k = s.lastIndexOf('}'); k !== -1 && ends.length < 5; k = s.lastIndexOf('}', k - 1)) ends.push(k);
    for (let i = s.indexOf('{'); i !== -1; i = s.indexOf('{', i + 1)) {
      for (const k of ends) {
        if (k <= i) continue;
        try { const o = JSON.parse(s.slice(i, k + 1)); if (o && typeof o === 'object') return o; } catch (e2) {}
      }
    }
  }
  return null;
};

const scored = $input.all().map((item, i) => {
  const base = { ...((jobs[i] || {}).json || {}) };
  delete base.llmPayload;
  const res = item.json || {};
  let txt = ''; try { txt = res.choices[0].message.content || ''; } catch (e) {}
  const p = parse(txt);
  // A failed call must not look like a fit of 0: that would record the role as rejected and
  // suppress it for rejectRecheckDays because of an API hiccup.
  const scoreOk = !!p && p.fit !== undefined && p.fit !== null && Number.isFinite(Number(p.fit));
  const err = res.error ? (res.error.message || JSON.stringify(res.error)) : 'unparseable response';
  return { ...base,
    fit: scoreOk ? Math.max(0, Math.min(100, Math.round(Number(p.fit)))) : null,
    scoreOk, scoreError: scoreOk ? '' : String(err).slice(0, 200),
    scoreReason: scoreOk ? String(p.reason || '') : '',
    missing: scoreOk && Array.isArray(p.missing) ? p.missing.slice(0, 3).map(String) : [],
    letter: '', subject: '', lang: '' };
});

// Letter slots go to the best FIT among passers (relevance breaks ties) - not to whichever
// passer happened to have the best title.
// Email first: email jobs and apply-yourself jobs have separate caps, and within each
// group the database backlog, then priorityRegion (the Netherlands), then fit.
const ok = s => s.scoreOk ? s.fit >= min : min <= 0;
// Automatic email only from minFitScoreEmail up. The scorer rates below 60 when core requirements are
// missing; 22 of the 71 mails sent 13 Oct - 9 Nov scored 20-38. Below the bar the address moves to
// publishedEmail: the job goes on the apply-yourself list with it, and Auto-send? never sees it.
const emailMin = Math.max(min, Number(cfg.minFitScoreEmail ?? min));
for (const s of scored) if (s.contactEmail && !(s.scoreOk ? s.fit >= emailMin : emailMin <= 0)) {
  s.publishedEmail = s.contactEmail; s.contactEmail = ''; s.applyChannel = 'link';
}
const pri = s => (cfg.priorityRegion && s.region === cfg.priorityRegion) ? 1 : 0;
// Moving to Amsterdam (2026-11-18): an ad that wants someone ALREADY living in the Netherlands (Booking.com: "does not
// come with relocation assistance, therefore candidates must be currently based in the Netherlands") is flagged in the
// reason, which the list and the export show, and gets a letter only after every other job. 8 of 381 ads measured.
const NL_RESIDENT = /\b(must|need to|needs to|required to|have to|should) (be )?(currently )?(based|located|living|live|reside|residing) in (the )?netherlands|\bcurrently (based|living|located|residing) in (the )?netherlands|\b(based|located|living|residing) in (the )?netherlands (is )?(required|a must|mandatory)|\bnetherlands[- ]based (candidates|applicants) only|\bonly (open to|considering|accepting) (candidates|applicants) (based|located|living|residing) in (the )?netherlands|\bdoes not (come with|offer|include) relocation|\bno relocation (support|assistance|package)/i;
for (const s of scored) if (s.country === 'NL' && NL_RESIDENT.test(String(s.description || ''))) {
  s.nlResidentOnly = true;
  s.scoreReason = 'Wants someone already living in the Netherlands. ' + (s.scoreReason || '');
}
const order = (a, b) => ((b.tier === 'backlog') - (a.tier === 'backlog'))   // database backlog first
  || ((a.nlResidentOnly ? 1 : 0) - (b.nlResidentOnly ? 1 : 0))               // wants an NL resident: letters last
  || (pri(b) - pri(a)) || (b.fit - a.fit) || ((b.relevance || 0) - (a.relevance || 0));
const mailable = scored.filter(s => s.contactEmail && ok(s)).sort(order);
const applyYourself = cfg.applyYourselfLetters === false ? []
  : scored.filter(s => !s.contactEmail && ok(s)).sort(order);
// Separate caps: Email Hunt can fill every email slot, and the apply-yourself list still needs letters.
const letterSlots = new Set(mailable.slice(0, cfg.maxPerRun || 8)
  .concat(applyYourself.slice(0, Number(cfg.maxApplyYourselfLetters ?? cfg.maxPerRun ?? 8))));

return scored.map(s => ({ json: { ...s,
  stage: !s.scoreOk && min > 0 ? 'score_failed'
       : s.scoreOk && s.fit < min ? 'rejected_fit'
       : letterSlots.has(s) ? 'letter'       // no address: Auto-send? skips it, it lands on the list with its letter
       : !s.contactEmail ? 'manual'          // no address and no slot left: on the list without a letter
       : 'deferred' } }));

const cfg = $('Config').first().json;
const sys = 'You score how well a candidate matches a job. Return STRICT JSON only: '
  + '{"fit":0,"reason":"...","missing":["..."]}. fit is 0-100 and must be strict: '
  + 'score below 60 when core requirements are absent. Judge only on evidence in the CV. '
  + 'reason: one English sentence. missing: up to 3 requirements the CV does not evidence. '
  + 'Do NOT write a cover letter.';

// All jobs at once: Score Job then fires the requests concurrently instead of one per loop turn.
return $input.all().map(({ json: j }) => {
  // Moving to Amsterdam (2026-11-18): the CV says Nuremberg, so tell the scorer location is no gap for Dutch jobs.
  const note = j.country === 'NL' && cfg.relocationNoteNL ? '\n\nCANDIDATE NOTE: ' + cfg.relocationNoteNL + ' Do not count location or work permit as a gap.' : '';
  const usr = 'CV:\n' + cfg.cvText + note + '\n\nJOB:\n' + j.title + ' at ' + j.company
    + ' (' + j.city + ')\n\n' + String(j.description || '').slice(0, 5000);
  return { json: { ...j, llmPayload: {
    model: cfg.scoreModel,
    messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }],
    max_tokens: 3000,
    temperature: Number(cfg.scoreTemperature ?? 0),
    reasoning: { effort: cfg.scoreEffort || 'low' },
    response_format: { type: 'json_object' } } } };
});

// The HTTP node emits exactly one item per request, in order, errors included - so detail[i]
// belongs to the i-th job on the IF's true branch.
const jobs = $('Needs Detail?').all(0);

const RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24}/g;
const BLOCK = /(noreply|no-reply|donotreply|postmaster|example\.|@arbeitsagentur\.|\.png|\.jpg)/i;
const TLD = '(?:com|de|net|org|eu|io|ai|nl|at|ch|info|jobs|gmbh|group|tech)';
const strip = h => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

// NL ads sometimes name the person to send the application to: "Apply now or reach out to Marco:
// marco@xomnia.com", "Send your application ... to Liesbeth at ...". Only that counts. An address in
// a sentence about questions, privacy, campus or open applications is not an application channel.
const MAILRX = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,24}/g;
const INVITE = /\b(apply|application|send (?:us )?your|reach out|get in touch|contact|mail (?:naar|to)|stuur|sollicit\w*|cv|resume)\b/i;
const NOT_APPLY = /\b(privacy|gdpr|personal data|data protection|erasure|rectification|campus|open applications?|exact role match|unsubscribe|press|media)\b/i;
const ASKING = /\b(questions?|information|info)\b/i, APPLYING = /\b(apply|application|cv|resume|sollicit\w*)\b/i;
const NOMAIL = /@(gmail|googlemail|hotmail|outlook|live|yahoo|icloud|gmx|web)\.|^(noreply|no-reply|donotreply|postmaster|privacy|gdpr|dpo|security|support|sales|press|legal|billing)@/i;
function applyEmail(text) {
  const d = String(text || '');
  for (const m of d.matchAll(MAILRX)) {
    const e = m[0].replace(/[.,;:)\]]+$/, '').toLowerCase();
    if (NOMAIL.test(e)) continue;
    const s = d.slice(Math.max(0, m.index - 160), m.index).split(/[.!?]\s/).pop();   // the lead-in sentence
    if (NOT_APPLY.test(s) || !INVITE.test(s)) continue;
    if (ASKING.test(s) && !APPLYING.test(s)) continue;                           // "for questions, contact ..."
    return e;
  }
  return '';
}

// Instaffo: an HTML page (the HTTP node hands it over as text in `data`); the ad is its
// schema.org JobPosting block.
const jobPosting = html => {
  for (const m of String(html).matchAll(/<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)) {
    try { const o = JSON.parse(m[1]); if (o && o['@type'] === 'JobPosting') return o; } catch (e) {}
  }
  return null;
};

// Four detail formats: Bundesagentur, Workday (jobPostingInfo), SmartRecruiters (jobAd sections),
// Instaffo (HTML page).
const describe = d => {
  if (d.stellenangebotsBeschreibung) return String(d.stellenangebotsBeschreibung);
  if (d.jobPostingInfo) return strip(d.jobPostingInfo.jobDescription);
  if (d.job_description) return strip(d.job_description);           // Eightfold (apply v2 detail)
  if (d.jobAd && d.jobAd.sections)
    return strip(Object.values(d.jobAd.sections).map(s => (s && s.text) || '').join(' '));
  const html = d.data || d.body;
  if (typeof html === 'string') { const jp = jobPosting(html); return jp ? strip(jp.description) : ''; }
  return '';
};

return $input.all().map((item, i) => {
  const base = (jobs[i] || {}).json || {};
  const d = item.json || {};
  const desc = describe(d);
  let email = '';
  // Only a Bundesagentur ad's address is an application channel. An address inside a Workday or
  // SmartRecruiters ad is usually "questions to recruiting@" - mailing a CV there, when the
  // employer wants its own portal, reads as not having read the ad.
  if (base.source === 'bundesagentur') for (const raw of (desc.match(RE) || [])) {
    let e = raw.replace(new RegExp('^([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+?\\.' + TLD + ')[A-ZÄÖÜ].*$'), '$1');
    e = e.replace(/[.,;:)\]]+$/, '').toLowerCase();
    if (BLOCK.test(e)) continue;
    email = e; break;
  }
  // NL: only an address the ad gives for applying (see applyEmail). An address found earlier, in
  // Filter Relevant, is kept - this node used to overwrite every non-Bundesagentur address with ''.
  if (!email && base.source !== 'bundesagentur') email = base.contactEmail
    || (base.country === 'NL' && $('Config').first().json.nlApplyByEmail !== false ? applyEmail(desc) : '');
  const wdLoc = d.jobPostingInfo ? [d.jobPostingInfo.location, (d.jobPostingInfo.country || {}).descriptor]
    .filter(Boolean).join(', ') : '';
  return { json: { ...base, description: desc.slice(0, 6000) || base.description || '',
    city: wdLoc || base.city, url: d.postingUrl || base.url,       // SmartRecruiters: public ad URL
    contactEmail: email,
    applyChannel: email ? 'email' : (base.source === 'bundesagentur' ? 'link' : base.applyChannel || 'link') } };
});

const cfg = $('Config').first().json;

const norm = s => String(s || '').toLowerCase().replace(/ß/g, 'ss')
  .normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim();
// One employer, many spellings: the registry says "Nebius", Arbeitnow "Nebius B.V.", the
// Bundesagentur "Nebius GmbH". Without folding legal forms, one-per-company and the history
// check both miss, and the same company gets a second application.
const LEGAL = /\b(gmbh|mbh|ag|se|kg|kgaa|co|ug|ohg|e v|ev|b v|bv|n v|nv|inc|llc|ltd|limited|plc|corp|corporation|sa|sas|sarl|srl|spa|holding|group|gruppe|deutschland|germany|netherlands|nederland|europe)\b/g;
const coKey = s => norm(s).replace(LEGAL, ' ').replace(/\s+/g, ' ').trim() || norm(s);

// Strip the noise that makes the same role look like three roles across boards.
const canon = t => norm(t)
  .replace(/\b(m w d|w m d|m f d|m w x|w m x|all genders|f m d|d f m)\b/g, '')
  .replace(/\b(senior|sr|medior|junior|jr|lead|staff|principal|expert)\b/g, '')
  .replace(/\b(fulltime|full time|permanent|unbefristet|remote|hybrid|onsite)\b/g, '')
  .replace(/\s+/g, ' ').trim();
const toks = s => new Set(canon(s).split(' ').filter(Boolean));
const jaccard = (a, b) => {
  const A = toks(a), B = toks(b);
  if (!A.size || !B.size) return 0;
  let i = 0; for (const x of A) if (B.has(x)) i++;
  return i / (A.size + B.size - i);
};

// History from Postgres. sent / queued / send_failed mean the company was approached: skip the
// whole company. rejected_fit means only that ROLE failed the gate: skip it (and near-identical
// reposts), but let the company's other roles compete. Without this the same highest-ranked,
// already-rejected role wins its company's slot every morning and the better role never gets scored.
const approached = new Set();
const rejected = new Map();
const manual = new Set();
// One employer under two names: a board says "Booking.com", an aggregator "Booking" or "Booking Holdings";
// "Picnic" and "picnic.app"; "IMC" and "IMC Trading". Legal forms are already folded by coKey; here the words
// that only decorate a name are ignored too, and then one name is the other plus more words. Without this the
// same ad is listed twice, once per source. (coKey itself stays as it is: the stored dedupe keys are built on it.)
const NOISE = /\b(com|app|io|nl|eu|holdings|technologies|technology|international|intl|management|company|global|benelux|emea)\b/g;
const core = k => k.replace(NOISE, ' ').replace(/\s+/g, ' ').trim() || k;
const sameCo = (a, b) => {
  if (a === b) return true;
  const x = core(a), y = core(b);
  return x === y || (x.length >= 3 && y.startsWith(x + ' ')) || (y.length >= 3 && x.startsWith(y + ' '));
};
const listed = new Map();        // canonical title -> company keys that role is already on the list under
const needsLetter = new Set();   // on the list without a letter: may come back for one
for (const r of $('Load History').all()) {
  const h = r.json || {};
  if (!h.dedupe_key) continue;
  const co = coKey(h.company);
  if (h.status === 'manual') {
    const t = String(h.dedupe_key).split('|').slice(1).join('|');
    if (!listed.has(t)) listed.set(t, []);
    listed.get(t).push(co);
  }
  if (h.status === 'rejected_fit') {
    if (!rejected.has(co)) rejected.set(co, []);
    rejected.get(co).push(String(h.dedupe_key).split('|').slice(1).join('|'));
  } else if (h.status === 'manual') {
    // On the apply-yourself list: that role already has a letter, the company stays open.
    // Without a letter it may come back once to get one (applyYourselfLetters).
    if (h.has_letter !== false || cfg.applyYourselfLetters === false) manual.add(String(h.dedupe_key));
    else needsLetter.add(String(h.dedupe_key));
  } else {
    approached.add(co);
  }
}
// While tuning in dry-run, re-score everything so a lowered minFitScore takes effect at once.
const skipRejected = !cfg.dryRun;

// Jobs come from Filter Relevant, NOT $input: this node's input is Load History, i.e. the
// Postgres rows. Ranking $input scored history rows as if they were jobs.
// Best-ranked first, so the pool keeps the strongest roles rather than whatever arrived first.
// Backlog first: jobs already in the database with an email address that were never sent.
// Bundesagentur ones get their ad re-fetched (Needs Detail?), which also re-checks the address;
// an expired ad yields no address, so the job lands on the manual list instead of being mailed.
const backlog = [].concat(($('Load Backlog').first().json || {}).backlog || [])
  .filter(r => r.dedupe_key && r.contact_email && r.title && r.company)
  .filter(r => (!(cfg.regions || []).length || cfg.regions.includes(r.region)))   // backlog skips Filter Relevant's region gate
  .map(r => ({ json: { source: r.source, tier: 'backlog', title: r.title, company: r.company,
    city: r.city || '', region: r.region || '', country: r.country || '', url: r.url || '',
    contactEmail: r.contact_email, description: '', homeoffice: false, isAgency: false, relevance: 1000,
    ref: r.source === 'bundesagentur' ? decodeURIComponent(String(r.url || '').split('/jobdetail/')[1] || '') : '',
    needsDetail: r.source === 'bundesagentur' } }));
// Filter Relevant has not run when the backlog alone filled the run (Fetch Needed? = false).
const fresh = (() => { try { return $('Filter Relevant').all(); } catch (e) { return []; } })();
const ranked = backlog.concat(fresh
  .filter(i => i.json && i.json.title && i.json.company)
  .sort((a, b) => (b.json.relevance || 0) - (a.json.relevance || 0)));

// Scoring is cheap and runs in parallel, so score a wider pool than we write letters for.
// Parse Score then gives the maxPerRun letter slots to the best FIT, not the best title.
const pool = Math.max(cfg.maxPerRun || 8, cfg.scorePoolSize || 24);
const picked = [];
const reserve = [];
const reserveCap = Math.max(0, Number(cfg.emailSearchMax ?? 300));
// Pool order: first priorityRegion (Amsterdam) up to priorityPoolShare of the pool, then everyone by relevance.
// Measured 2026-11-09: without the share Amsterdam got 3 of 60 slots - Bavarian and Berlin Bundesagentur AI titles
// outrank it. A job that can be emailed (an address, or a Bundesagentur ad whose address is in the detail) stays
// one per company per run; apply-yourself jobs may take up to maxRolesPerCompany, so Booking.com's 19
// engineering roles do not trickle in one a run.
const perCo = Math.max(1, Number(cfg.maxRolesPerCompany ?? 1));
const quota = cfg.priorityRegion ? Math.round(pool * Math.min(1, Math.max(0, Number(cfg.priorityPoolShare ?? 0)))) : 0;
const emailCapable = j => !!j.contactEmail || j.source === 'bundesagentur';
const coCount = new Map();          // company -> roles taken; Infinity once an email-capable job is taken
const taken = new Set();
const pickedCos = { has: co => coCount.has(co) };   // reserve logic below only needs has()
// History under the employer's other names too (looked up once per company).
const memo = f => { const m = new Map(); return k => { if (!m.has(k)) m.set(k, f(k)); return m.get(k); }; };
const isApproached = memo(co => approached.has(co) || [...approached].some(a => sameCo(a, co)));
const rejectedOf = memo(co => [...rejected.keys()].filter(k => sameCo(k, co)).flatMap(k => rejected.get(k)));
const eligible = (j, co) => co && !isApproached(co)
  && !(skipRejected && rejectedOf(co).some(t => jaccard(t, j.title) >= 0.6))
  // listed already - under this name, or under the employer's other name - unless it now names someone to email
  && !((manual.has(co + '|' + canon(j.title)) || (listed.get(canon(j.title)) || []).some(c => c !== co && sameCo(c, co))) && !j.contactEmail);
const room = (j, co) => emailCapable(j) ? !coCount.has(co) : (coCount.get(co) || 0) < perCo;
// The same role twice in one run: from a board and from a search source, or reposted on the same source.
// `ranked` is best first and boards carry the curated/watchlist bonus, so the board's copy (full ad text, direct
// link) is the one that stays.
const runTitles = new Map();     // canonical title -> company keys taken this run
const dupInRun = (j, co) => (runTitles.get(canon(j.title)) || []).some(c => sameCo(c, co));
// A listed role without a letter comes back for one - but only as many per run as there are letters to give.
// Unbounded, they refill the pool every run and the new roles behind them are never scored (measured
// 2026-11-16: 150 such roles on the list; of Amsterdam's 40 slots, 20 went to them and 15 to new roles).
const letterBudget = Math.max(0, Number(cfg.maxApplyYourselfLetters ?? cfg.maxPerRun ?? 8));
let comeBacks = 0;
const comesBack = (j, co) => !j.contactEmail && needsLetter.has(co + '|' + canon(j.title));
// Employers this run reads directly (registry and watchlist boards). englishjobsearch.nl rewrites titles
// ("Machine learning engineer in inference platforms" for Booking.com's "Machine Learning Engineer - Inference
// Platform"), so its copy of such an employer's ad cannot be matched to the board's by title. The board is the
// complete list for that employer, so the aggregator's copies of its ads are dropped.
const direct = (() => { try { return [...new Set($('ATS Registry').all().map(i => coKey((i.json || {}).name)).filter(Boolean))]; } catch (e) { return []; } })();
const hasFeed = memo(co => direct.some(d => sameCo(d, co)));
const usable = (j, co) => eligible(j, co) && room(j, co) && !dupInRun(j, co) && !(comesBack(j, co) && comeBacks >= letterBudget)
  && !(j.source === 'englishjobs' && hasFeed(co));
const take = (item, idx) => {
  const j = item.json, co = coKey(j.company), t = canon(j.title);
  coCount.set(co, emailCapable(j) ? Infinity : (coCount.get(co) || 0) + 1);
  taken.add(idx);
  if (comesBack(j, co)) comeBacks++;
  if (!runTitles.has(t)) runTitles.set(t, []);
  runTitles.get(t).push(co);
  picked.push({ ...j, companyKey: co, dedupeKey: co + '|' + t });
};
ranked.forEach((item, idx) => {
  const j = item.json, co = coKey(j.company);
  if (picked.length < quota && !j.emailReserve && j.region === cfg.priorityRegion && usable(j, co)) take(item, idx);
});
ranked.forEach((item, idx) => {
  const j = item.json, co = coKey(j.company);
  if (taken.has(idx) || j.emailReserve || picked.length >= pool) return;
  if (usable(j, co)) take(item, idx);
});
// Beyond the pool or below the title gate, but it may carry an address: Email Hunt's reserve (one per company).
ranked.forEach((item, idx) => {
  const j = item.json, co = coKey(j.company);
  if (taken.has(idx) || reserve.length >= reserveCap || !(j.contactEmail || j.source === 'bundesagentur')) return;
  if (!eligible(j, co) || coCount.has(co)) return;
  coCount.set(co, Infinity);
  reserve.push({ ...j, reserve: true, companyKey: co, dedupeKey: co + '|' + canon(j.title) });
});
// Reserve order: priority region first, then relevance - the bar drops one step at a time.
const pri = j => (cfg.priorityRegion && j.region === cfg.priorityRegion) ? 1 : 0;
reserve.sort((a, b) => (pri(b) - pri(a)) || ((b.relevance || 0) - (a.relevance || 0)));

// Never return nothing: an empty output stops the workflow before the digest, and a morning
// with no digest looks exactly like a morning where every source broke.
if (!picked.length && !reserve.length) return [{ json: { noCandidates: true } }];
return picked.concat(reserve).map(j => ({ json: j }));

const cfg = $('Config').first().json;
const pos = (cfg.titleMustMatch || [])
  .concat(cfg.includeFullStack ? (cfg.titleMustMatchFullStack || []) : [])
  .map(s => String(s).toLowerCase());
const neg = (cfg.titleExclude || []).map(s => String(s).toLowerCase());

// "Engineer" at Isar Aerospace can mean launch vehicles; at Proxima Fusion, plumbing.
// Broad intake at curated companies needs a hard software boundary.
const NOTSW = /\b(mechanical|electrical|plumbing|mep|hvac|building services|civil|chemical|structural|thermal|propulsion|launch vehicle|ait|avionics|manufacturing|production|assembly|welding|machinist|technician|facilities|maintenance|supply chain|logistics|warehouse|driver|nurse|chef|culinary|barista|cleaner|field service|hardware|pcb|rf design)\b/i;

// Netherlands: an ad written in Dutch, or an English one that demands fluent Dutch, is out of reach
// without Dutch - Conflux and adesso in Utrecht write every engineering ad in Dutch. A requirement
// softened in the same sentence ("Dutch is a plus", "or want to learn", "not required") keeps the
// job, and so does an ad too short to tell. Measured 2026-10-13 on the 42 NL boards.
const NLW = /\b(het|een|van|voor|met|jij|jouw|wij|onze|bij|naar|zijn|wordt|ervaring|kennis|werkzaamheden|functie|vacature|ook|niet|wat|hoe|heb|hebt|je|binnen|zoeken|bieden)\b/gi;
const ENW = /\b(the|and|you|with|for|our|your|will|are|is|of|to|we|this|that|team|experience)\b/gi;
function needsDutch(text) {
  const d = String(text || '').slice(0, 8000);
  const nl = (d.slice(0, 4000).match(NLW) || []).length, en = (d.slice(0, 4000).match(ENW) || []).length;
  if (nl + en >= 15 && nl > en) return true;                       // written in Dutch
  const re = /\bdutch\b/gi;
  let m;
  while ((m = re.exec(d))) {
    const s = d.slice(Math.max(0, m.index - 120), m.index).split(/[.!?;\u2022\u2705\u274c]\s/).pop()
      + d.slice(m.index, m.index + 120).split(/[.!?;\u2022\u2705\u274c]\s/)[0];
    // About the language, not "Dutch GAAP" or "Dutch labour law".
    if (!/\b(fluen\w*|native|proficien\w*|speak\w*|spoken|written|command)\b/i.test(s)) continue;
    if (/\b(plus|bonus|advantage\w*|prefer\w*|nice|asset|beneficial|welcome|useful|helpful|optional|ideally|learn\w*|and\/or|(?:english|german) or dutch|not (?:required|essential|necessary|needed|mandatory|a must)|or (?:another|danish|french|german|english))\b/i.test(s)) continue;
    return true;
  }
  return false;
}

// NL ads sometimes name the person to send the application to: "Apply now or reach out to Marco:
// marco@xomnia.com", "Send your application ... to Liesbeth at ...". Only that counts. An address in
// a sentence about questions, privacy, campus or open applications is not an application channel.
const MAILRX = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,24}/g;
const INVITE = /\b(apply|application|send (?:us )?your|reach out|get in touch|contact|mail (?:naar|to)|stuur|sollicit\w*|cv|resume)\b/i;
const NOT_APPLY = /\b(privacy|gdpr|personal data|data protection|erasure|rectification|campus|open applications?|exact role match|unsubscribe|press|media)\b/i;
const ASKING = /\b(questions?|information|info)\b/i, APPLYING = /\b(apply|application|cv|resume|sollicit\w*)\b/i;
const NOMAIL = /@(gmail|googlemail|hotmail|outlook|live|yahoo|icloud|gmx|web)\.|^(noreply|no-reply|donotreply|postmaster|privacy|gdpr|dpo|security|support|sales|press|legal|billing)@/i;
function applyEmail(text) {
  const d = String(text || '');
  for (const m of d.matchAll(MAILRX)) {
    const e = m[0].replace(/[.,;:)\]]+$/, '').toLowerCase();
    if (NOMAIL.test(e)) continue;
    const s = d.slice(Math.max(0, m.index - 160), m.index).split(/[.!?]\s/).pop();   // the lead-in sentence
    if (NOT_APPLY.test(s) || !INVITE.test(s)) continue;
    if (ASKING.test(s) && !APPLYING.test(s)) continue;                           // "for questions, contact ..."
    return e;
  }
  return '';
}

// Rank titles so the handful that reach expensive letter generation are the best ones.
function relevance(title, j) {
  const t = ' ' + String(title).toLowerCase() + ' ';
  let s = 0;
  if (/\b(ai|a\.i\.|ki|künstliche intelligenz|llm|genai|generative|nlp|computer vision|bildverarbeitung|deep learning|agentic|inference)\b/.test(t)) s += 8;
  if (/\b(machine learning|ml|mlops|applied scien\w*|research engineer)\b/.test(t)) s += 8;
  if (/\b(data scien\w*|data engineer)\b/.test(t)) s += 4;
  // Forward Deployed Engineer (2026-11-18): customer-facing engineering, mostly at AI companies. Its own +10, so a
  // plain "Forward Deployed Engineer" passes every title gate (it scored 0-2 before and was dropped everywhere).
  // Engineer, developer or scientist must follow within three words: Onodrim's "Forward Deployed Operator - Legal &
  // Compliance" and "... - Hardware Engineering" are not engineering roles.
  if (/\bforward[- ]deployed(?:\s+\S+){0,3}?\s+(engineer|developer|scientist)\b|\bfde\b/.test(t)) s += 10;
  // Full-stack family, EN or DE. Scored ONCE, never both - "Fullstack-Entwickler" matches
  // both patterns and would otherwise double-count and outrank an ML role.
  // Below AI on purpose: these fill the tail of the per-run cap, not the head.
  if (/\b(software engineer|software developer|backend|back-end|frontend|front-end|full.?stack|platform engineer|web developer|web engineer)\b/.test(t)
      || /(softwareentwickler|software-entwickler|fullstack-?entwickler|backend-?entwickler|frontend-?entwickler|webentwickler|softwareingenieur)/.test(t)) s += 5;
  if (/\b(cloud|devops|sre|infrastructure|security)\b/.test(t)) s += 1;
  if (/\b(senior|staff|principal)\b/.test(t)) s += 1;
  if (/\b(manager|lead|head)\b/.test(t)) s -= 3;
  if (/\b(android|ios|mobile|embedded|firmware)\b/.test(t)) s -= 2;
  if (j.tier === 'curated') s += 2;          // known-good employer
  else if (j.tier === 'watchlist') s += 1;   // an employer you chose to watch
  if (j.homeoffice) s += 1;
  return s;
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  // Only the regions in Config. Every source sets region; a job outside them is never scored or mailed.
  if ((cfg.regions || []).length && !cfg.regions.includes(j.region)) continue;
  const t = ' ' + String(j.title || '').toLowerCase() + ' ';
  if (!j.title || !j.company) continue;
  if (/^(unbekannt|unknown|vertraulich|confidential)$/i.test(String(j.company).trim())) continue;
  if (neg.some(n => t.includes(n))) continue;
  if (NOTSW.test(j.title)) continue;
  if (j.country === 'NL' && cfg.skipDutchRequired !== false && needsDutch(j.title + '. ' + (j.description || ''))) continue;
  // Curated boards are pre-filtered by company, so don't also demand "AI" in the title.
  // Only the hand-picked AI companies skip the title check. A watchlist employer like
  // Siemens lists thousands of roles; there the title has to say what the role is.
  if (j.tier !== 'curated') {
    if (!pos.some(p => p && t.includes(p))) continue;
    if (j.tier === 'search' && cfg.excludeAgencies && j.isAgency) continue;
  }
  const rel = relevance(j.title, j);
  // The Netherlands has far fewer roles than Berlin and Bayern, and most arrive from search sources
  // without the curated bonus, so it can have its own, lower gate.
  const gate = j.country === 'NL' && cfg.minRelevanceNL !== undefined && cfg.minRelevanceNL !== ''
    ? Number(cfg.minRelevanceNL) : (cfg.minRelevance ?? 3);
  const mail = j.country === 'NL' && cfg.nlApplyByEmail !== false && !j.contactEmail ? applyEmail(j.description) : '';
  // Below the gate, a role that can be emailed (a Bundesagentur ad, whose address is in the detail;
  // an NL ad naming someone) is kept as a reserve down to minRelevanceEmail. Email Hunt draws on it,
  // best first, only when the run is short of jobs to email. Everything else below the gate is dropped.
  const below = rel < gate;
  if (below && !(rel >= Number(cfg.minRelevanceEmail ?? gate) && (j.source === 'bundesagentur' || mail))) continue;
  out.push({ json: { ...j, relevance: rel, ...(below ? { emailReserve: true } : {}),
    ...(mail ? { contactEmail: mail, applyChannel: 'email' } : {}) } });
}
return out;

const cfg = $('Config').first().json;
const RX = {
  berlin:    /\bberlin\b/i,
  bayern:    /\b(m[uü]nchen|munich|n[uü]rnberg|nuremberg|bayern|bavaria|augsburg|erlangen|f[uü]rth|herzogenaurach|forchheim|ingolstadt|regensburg|w[uü]rzburg|bamberg|garching|unterf[oö]hring|unterschlei[sß]heim|ismaning|oberpfaffenhofen|we[sß]ling|planegg|martinsried|starnberg|freising|rosenheim|landshut|passau|bayreuth|aschaffenburg|schweinfurt)\b/i,
  amsterdam: /\b(amsterdam|amstelveen|diemen|duivendrecht|badhoevedorp|schiphol|hoofddorp|haarlem|zaandam|purmerend|weesp|aalsmeer|uithoorn|almere|hilversum|bussum|naarden|huizen|amersfoort|utrecht|nieuwegein|zeist|houten|bunnik|woerden|maarssen|leiden|katwijk|noordwijk|delft|den haag|the hague|gravenhage|rijswijk|zoetermeer|leidschendam|voorburg|rotterdam|capelle|schiedam|gouda|eindhoven|noord-holland|zuid-holland|north holland|south holland|netherlands|nederland)\b/i
};
const want = cfg.regions || [];
const strip = h => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const cutoff = Date.now() - (cfg.maxDaysOld || 7) * 86400000;

const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.data || [])) {
    const loc = j.location || '';
    // A city region first; elsewhere only a remote job (Arbeitnow's own flag) counts, as `remote`.
    const region = want.find(w => RX[w] && RX[w].test(loc)) || (j.remote && want.includes('remote') ? 'remote' : '');
    if (!region) continue;
    // created_at is unix seconds
    const ts = Number(j.created_at || 0) * 1000;
    if (ts && ts < cutoff) continue;
    out.push({ json: {
      source: 'arbeitnow', tier: 'search', ref: String(j.slug || ''),
      title: j.title || '', company: j.company_name || '',
      city: loc, region, country: region === 'amsterdam' ? 'NL' : 'DE',
      postedAt: ts ? new Date(ts).toISOString().slice(0, 10) : '',
      homeoffice: !!j.remote,
      isAgency: /recruit|staffing|personal|zeitarbeit|uberlassung/i.test(j.company_name || ''),
      url: j.url || '', description: strip(j.description).slice(0, 6000),
      contactEmail: '', applyChannel: 'link'
    }});
  }
}
return out;

const cfg = $('Config').first().json;
// Plain paginated feed - no server-side filtering, so pull N pages and filter locally.
const n = Math.max(1, Math.min(cfg.arbeitnowPages || 5, 15));
return Array.from({ length: n }, (_, i) => ({ json: { page: i + 1 } }));

// One Adzuna response per query, in order - each carries the country/region it was asked for.
const queries = $('Build NL Queries').all();
// Prefer the job's own city; fall back to the region the query asked for.
const RX = {
  berlin:    /\bberlin\b/i,
  bayern:    /\b(m[uü]nchen|munich|n[uü]rnberg|nuremberg|bayern|augsburg|erlangen|f[uü]rth|herzogenaurach|ingolstadt|regensburg)\b/i,
  amsterdam: /\b(amsterdam|amstelveen|diemen|duivendrecht|badhoevedorp|schiphol|hoofddorp|haarlem|zaandam|purmerend|weesp|aalsmeer|uithoorn|almere|hilversum|bussum|naarden|huizen|amersfoort|utrecht|nieuwegein|zeist|houten|bunnik|woerden|maarssen|leiden|katwijk|noordwijk|delft|den haag|the hague|gravenhage|rijswijk|zoetermeer|leidschendam|voorburg|rotterdam|capelle|schiedam|gouda|eindhoven|noord-holland|zuid-holland|north holland|south holland|netherlands|nederland)\b/i
};
const out = [];
// Overlapping centres and similar terms return the same ad several times.
const seen = new Set();
$input.all().forEach((item, i) => {
  const q = (queries[i] || {}).json || {};
  const nl = q.country !== 'de';
  for (const j of (item.json.results || [])) {
    const key = (nl ? 'nl' : 'de') + '|' + (j.id || j.redirect_url || '');
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      source: 'adzuna', tier: 'search', ref: String(j.id || ''),
      title: j.title || '', company: (j.company || {}).display_name || '',
      city: (j.location || {}).display_name || q.where || '',
      region: Object.keys(RX).find(r => RX[r].test((j.location || {}).display_name || '')) || q.region || 'amsterdam',
      country: nl ? 'NL' : 'DE',
      postedAt: (j.created || '').slice(0, 10),
      homeoffice: /remote|hybrid|thuiswerk|homeoffice/i.test(j.description || ''),
      isAgency: /recruit|staffing|uitzend|detacher|werving|personaldienst|zeitarbeit|personalvermittlung/i
        .test((j.company || {}).display_name || ''),
      url: j.redirect_url || '', description: (j.description || '').replace(/<[^>]+>/g, ' '),
      contactEmail: '', applyChannel: 'link'
    }});
  }
});
return out;

const cfg = $('Config').first().json;
// Adzuna is the aggregator for BOTH countries: the Netherlands (the only broad NL source) and, with
// adzunaGermany, the German cities too - it indexes company career sites the Bundesagentur misses.
// Returning [] when switched off means Fetch Adzuna never runs, so a missing credential costs nothing.
if (!cfg.useAdzuna) return [];
const want = cfg.regions || [];
// Free Adzuna keys allow 25 calls a minute and 250 a day (1000 a week, 2500 a month). Fetch Adzuna
// paces itself under the minute limit; this cap keeps a few runs a day under the rest.
const budget = Math.max(0, Number(cfg.adzunaMaxCalls ?? 60));
const out = [];
const add = q => { if (out.length < budget) out.push({ json: { ...q, days: cfg.maxDaysOld, size: 50 } }); };

// Netherlands first: it has no other broad source, Germany has the Bundesagentur.
// Each query returns only the 50 newest ads, so one 60 km circle around Amsterdam saw the newest 50
// for the whole Randstad. Several centres at a smaller radius each get their own 50; Amsterdam,
// Utrecht and Rotterdam at 30 km reach Haarlem, Almere, Hilversum, Amersfoort, Leiden, Den Haag and
// Delft. English terms only: "KI" and "Softwareentwickler" find nothing useful there.
if (want.includes('amsterdam')) {
  const centres = [].concat(cfg.nlLocations || cfg.nlLocation || 'Amsterdam');
  const terms = cfg.nlKeywords
    ? cfg.nlKeywords.concat(cfg.includeFullStack ? (cfg.nlKeywordsFullStack || []) : [])
    : (cfg.keywords || []).concat(cfg.includeFullStack ? (cfg.keywordsFullStack || []) : []);
  // Term-major, so a tight budget drops the least important terms rather than a whole city.
  for (const what of terms) for (const where of centres)
    add({ country: 'nl', where, distance: cfg.nlRadiusKm, region: 'amsterdam', what });
}
if (cfg.adzunaGermany) {
  const terms = (cfg.keywords || []).concat(cfg.includeFullStack ? (cfg.keywordsFullStack || []) : []);
  const cities = (cfg.deLocations || []).map(wo => ({ wo, region: /berlin/i.test(wo) ? 'berlin' : 'bayern' }))
    .filter(c => want.includes(c.region));
  for (const what of terms) for (const c of cities)
    add({ country: 'de', where: c.wo, distance: cfg.deRadiusKm, region: c.region, what });
}
return out;

// The v6 API no longer returns istPrivateArbeitsvermittlung / istArbeitnehmerUeberlassung,
// so excludeAgencies silently did nothing for Bundesagentur ads. The name has to do the work.
const AGENCY = /personalvermittlung|personaldienst|personalberatung|zeitarbeit|arbeitnehmer.?[uü]berlassung|recruiting|recruitment|staffing|arbeitsvermittlung|personalmanagement|talent partner|tempton|personalservice|personal service|headhunt|executive search|ratbacher|hays|randstad|manpower|adecco|gulp|solcom|etengo|computer futures|experis|brunel|ferchau|amadeus fire|\bdis ag\b/i;
// One response per query, in order. The query's own centre decides the region: the Berlin search
// (50 km) also returns Potsdam, Hennigsdorf and Nuthetal, whose Bundesland is Brandenburg - the old
// rule ("not Berlin, so Bayern") filed those under Bayern.
const queries = $('Build DE Queries').all();
// Fully remote in the title: explicit ("100% remote", "full remote", "deutschlandweit") or a plain "remote"
// without a softener ("remote möglich", "hybrid", "2 Tage"). "Dresden oder remote" counts.
const fullyRemote = t => /\b(100\s?%\s?(remote|home.?office)|full(y)?[- ]remote|remote[- ]first|vollst[aä]ndig remote|deutschlandweit|bundesweit|ortsunabh[aä]ngig)\b/i.test(t)
  || (/\bremote\b/i.test(t) && !/(m[oö]glich|optional|hybrid|teilweise|anteilig|tage|days|vor ort)/i.test(t));
const out = [];
$input.all().forEach((item, i) => {
  const q = (queries[i] || {}).json || {};
  const qRegion = q.region || (/berlin/i.test(q.wo || '') ? 'berlin' : 'bayern');
  for (const j of (item.json.ergebnisliste || [])) {
    // The nationwide remote search: a job in Bayern or Berlin keeps its region (any work mode is fine
    // there); anywhere else it must say fully remote in the title, or it is dropped.
    let region = qRegion;
    if (qRegion === 'remote') {
      const state = String((((j.stellenlokationen || [])[0] || {}).adresse || {}).region || '').toUpperCase();
      region = state === 'BAYERN' ? 'bayern' : state === 'BERLIN' ? 'berlin'
        : fullyRemote(j.stellenangebotsTitel || '') ? 'remote' : '';
      if (!region) continue;
    }
    const adr = ((j.stellenlokationen || [])[0] || {}).adresse || {};
    const ref = j.referenznummer || '';
    const ort = adr.ort || '';
    out.push({ json: {
      source: 'bundesagentur', tier: 'search', ref,
      title: j.stellenangebotsTitel || '', company: j.firma || j.allianzpartnerName || '',
      city: ort, region, country: 'DE',
      postedAt: j.datumErsteVeroeffentlichung || (j.veroeffentlichungszeitraum || {}).von || '',
      homeoffice: !!j.homeofficemoeglich,
      isAgency: !!(j.istPrivateArbeitsvermittlung || j.istArbeitnehmerUeberlassung) || AGENCY.test(j.firma || ''),
      url: ref ? 'https://www.arbeitsagentur.de/jobsuche/jobdetail/' + encodeURIComponent(ref) : '',
      description: '', needsDetail: true, contactEmail: '', applyChannel: 'unknown'
    }});
  }
});
return out;

const cfg = $('Config').first().json;
const terms = (cfg.keywords || []).concat(cfg.includeFullStack ? (cfg.keywordsFullStack || []) : []);
// A query returns up to `perQuery` (max 100) per page; baPages > 1 reads deeper. Measured
// 2026-09-24: "KI" in München alone had 609 postings in 30 days - one 25-row page saw 4%.
const pages = Math.max(1, Math.min(Number(cfg.baPages) || 1, 5));
// The list is ordered by relevance, not by date, and nearly every relevant ad is on the first pages (measured
// 2026-11-18 at gate 8: 170 of 178 on pages 1-3). A few searches run past 300 ads ("KI" in Bayern: 1,060); those are
// read to the end (baDeepTerms, baDeepPages): 8 more roles for about 13 requests.
const deep = new Set((cfg.baDeepTerms || []).map(s => String(s).toLowerCase()));
const deepPages = Math.max(pages, Math.min(Number(cfg.baDeepPages) || pages, 15));
const want = cfg.regions || [];
const size = Math.min(cfg.perQuery || 100, 100);
const out = [];
for (const wo of cfg.deLocations) {
  // "Bayern" is a whole-state search (the API answers BUNDESLANDSUCHE and ignores umkreis): 1888 "KI" ads,
  // against 901 within 50 km of München. Any other location is a radius search around a city.
  const region = /berlin/i.test(wo) ? 'berlin' : 'bayern';
  if (!want.includes(region)) continue;
  for (const was of terms) for (let page = 1; page <= (deep.has(String(was).toLowerCase()) ? deepPages : pages); page++)
    out.push({ json: { was, wo, page, umkreis: cfg.deRadiusKm, size, days: cfg.maxDaysOld, region } });
}
// The rest of Germany: fully remote only. A nationwide search (wo "Deutschland" = LANDSUCHE) for
// "<term> remote"; Normalize DE keeps a job only if its title says fully remote, unless it lies in
// Bayern or Berlin anyway. Measured 2026-11-09: 32 such dev roles, 17 of them with an address.
if (want.includes('remote')) for (const was of (cfg.remoteKeywords || [])) for (let page = 1; page <= 2; page++)
  out.push({ json: { was, wo: 'Deutschland', page, umkreis: cfg.deRadiusKm, size, days: cfg.maxDaysOld, region: 'remote' } });
return out;

const cfg = $('Config').first().json;
const RX = {
  berlin:    /\bberlin\b|\bBE,\s*DE\b/i,
  bayern:    /\b(m[uü]nchen|munich|n[uü]rnberg|nuremberg|bayern|bavaria|augsburg|erlangen|f[uü]rth|herzogenaurach|forchheim|ingolstadt|regensburg|w[uü]rzburg|bamberg|garching|unterf[oö]hring|unterschlei[sß]heim|ismaning|oberpfaffenhofen|we[sß]ling|planegg|martinsried|starnberg|freising|rosenheim|landshut|passau|bayreuth|aschaffenburg|schweinfurt)\b|\bBY,\s*DE\b/i,
  // Checked after the cities: a remote role open to Germany (or EU/EMEA-wide) - the rest of Germany only counts remote.
  remote:    /^(?=.*\b(remote|home.?office)\b)(?=.*\b(germany|deutschland|dach|europe|european union|eu|emea|cet)\b)/i,
  amsterdam: /\b(amsterdam|amstelveen|diemen|duivendrecht|badhoevedorp|schiphol|hoofddorp|haarlem|zaandam|purmerend|weesp|aalsmeer|uithoorn|almere|hilversum|bussum|naarden|huizen|amersfoort|utrecht|nieuwegein|zeist|houten|bunnik|woerden|maarssen|leiden|katwijk|noordwijk|delft|den haag|the hague|gravenhage|rijswijk|zoetermeer|leidschendam|voorburg|rotterdam|capelle|schiedam|gouda|eindhoven|noord-holland|zuid-holland|north holland|south holland|netherlands|nederland)\b/i
};
// At an AI-native company the COMPANY is the filter, not the title: their ML roles are
// called "Senior Software Engineer". So accept engineering broadly and let fit scoring decide.
const ENG = /\b(engineer|engineering|developer|entwickler|scientist|science|research|researcher|machine learning|deep learning|architect|ml|ai|ki|llm|data|platform|infrastructure|backend|full.?stack|devops|sre|software|python)\b/i;
const NOPE = new RegExp((cfg.titleExclude || []).map(s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') || '$^', 'i');
const want = cfg.regions || [];

const strip = h => String(h || '')
  .replace(/<!\[CDATA\[|\]\]>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&amp;/g, '&').replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d))
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const tag = (xml, t) => { const m = xml.match(new RegExp('<' + t + '>([\\s\\S]*?)</' + t + '>')); return m ? m[1] : ''; };
const blocks = (xml, t) => xml.match(new RegExp('<' + t + '>[\\s\\S]*?</' + t + '>', 'g')) || [];

// One response per request, in order: fetched as TEXT so an ATS that returns a bare JSON array
// (Lever) stays one item instead of being split into one item per job. Merge Boards appends the
// Workday (POST) responses first, then the GET ones - the same order as the IF's two outputs.
const reg = $('Is POST?').all(0).concat($('Is POST?').all(1));
const inputs = $input.all();
const out = [];
const seen = new Set();
for (let i = 0; i < inputs.length; i++) {
  const meta = (reg[i] || {}).json || {};
  const ats = meta.ats, company = meta.name || meta.token;
  if (!ats) continue;
  const raw = typeof (inputs[i].json || {}).data === 'string' ? inputs[i].json.data : '';
  let d = {};
  try { d = JSON.parse(raw); } catch (e) { d = {}; }

  let rows = [];
  if (ats === 'greenhouse' && Array.isArray(d.jobs)) {
    rows = d.jobs.map(j => ({ id: j.id, title: j.title, loc: (j.location || {}).name || '',
      url: j.absolute_url, desc: strip(j.content), posted: (j.updated_at || '').slice(0, 10) }));
  } else if (ats === 'lever' && Array.isArray(d)) {
    rows = d.map(j => ({ id: j.id, title: j.text, loc: ((j.categories || {}).location) || '',
      alt: ((j.categories || {}).allLocations || []).concat(j.workplaceType === 'remote' ? [((j.categories || {}).location || '') + ' (remote)'] : []),
      url: j.hostedUrl, desc: strip(j.descriptionPlain || j.description),
      posted: j.createdAt ? new Date(j.createdAt).toISOString().slice(0, 10) : '' }));
  } else if (ats === 'recruitee' && Array.isArray(d.offers)) {
    // country_code is exact - free-text location says "Remote job" for US roles too.
    rows = d.offers.filter(j => j.country_code === 'NL' || j.country_code === 'DE' || j.remote).map(j => ({
      id: j.id, title: j.title,
      loc: [j.city, j.location, j.country, j.remote ? 'remote' : ''].filter(Boolean).join(' '),
      url: j.careers_url || j.careers_apply_url,
      desc: strip([j.description, j.requirements].filter(Boolean).join(' ')),
      posted: String(j.published_at || j.created_at || '').slice(0, 10) }));
  } else if (ats === 'ashby' && Array.isArray(d.jobs)) {
    rows = d.jobs.map(j => ({ id: j.id || j.jobId, title: j.title, loc: j.location || '',
      alt: (j.secondaryLocations || []).map(s => s && s.location).filter(Boolean)
        .concat(j.isRemote || j.workplaceType === 'Remote' ? [(j.location || '') + ' (remote)'] : []),
      url: j.jobUrl || j.applyUrl, desc: strip(j.descriptionPlain || j.descriptionHtml),
      posted: (j.publishedAt || '').slice(0, 10) }));
  } else if (ats === 'personio' && raw.includes('<position>')) {
    rows = blocks(raw, 'position').map(p => {
      const id = strip(tag(p, 'id'));
      return { id, title: strip(tag(p, 'name')),
        loc: blocks(p, 'office').map(strip).join(' '),        // main + additionalOffices
        url: `https://${String(meta.token).includes('.') ? meta.token : meta.token + '.jobs.personio.de'}/job/${id}`,
        desc: strip(blocks(p, 'value').join(' ')), posted: strip(tag(p, 'createdAt')).slice(0, 10) };
    });
  } else if (ats === 'successfactors' && raw.includes('<item>')) {
    // Titles look like "Data Engineer (all genders) (Berlin, BE, DE, 10115)" - the last
    // parenthesis is the location. The RSS description carries the full ad.
    rows = blocks(raw, 'item').map(it => {
      const full = strip(tag(it, 'title'));
      const m = full.match(/\(([^()]*,\s*[A-Z]{2}(?:,[^()]*)?)\)\s*$/);
      const link = strip(tag(it, 'link'));
      return { id: (link.match(/\/(\d+)\/?(?:\?|$)/) || [])[1] || link, title: m ? full.slice(0, m.index).trim() : full,
        loc: m ? m[1] : full, url: link.replace(/\?feedId=[^&]*&?$/, ''),
        desc: strip(tag(it, 'description')), posted: '' };
    });
  } else if (ats === 'workday' && Array.isArray(d.jobPostings)) {
    // The list has no description and sometimes only a site code as location; the detail
    // endpoint has both, fetched later for the shortlist only.
    const [tenant, wd, site] = String(meta.token).split('|');
    const base = `https://${tenant}.${wd}.myworkdayjobs.com`;
    rows = d.jobPostings.map(j => ({ id: (j.bulletFields || [])[0] || j.externalPath, title: j.title,
      loc: [j.locationsText, String(j.externalPath || '').split('/')[2]].filter(Boolean).join(' ').replace(/-/g, ' '),
      url: `${base}/${site}${j.externalPath}`, desc: '', posted: '',
      detailUrl: `${base}/wday/cxs/${tenant}/${site}${j.externalPath}`,
      countryFiltered: !!(meta.options && meta.options.facets && Object.keys(meta.options.facets).length) }));
  } else if (ats === 'jibe' && Array.isArray(d.jobs)) {
    rows = d.jobs.map(x => x.data || x).map(j => ({ id: j.req_id || j.slug, title: j.title,
      loc: [j.city, j.state, j.country].filter(Boolean).join(', '),
      url: `https://${meta.token}/${meta.options && meta.options.site || 'booking'}/jobs/${j.slug}`,
      desc: strip(j.description), posted: String(j.posted_date || '').slice(0, 10) }));
  } else if (ats === 'sitemap' && raw.includes('<loc>')) {
    // ING and ABN AMRO: job URLs carry the title (and for ING the city); the ad itself comes from the page's
    // schema.org JobPosting, fetched by Fetch Detail for the scoring pool only.
    const o = meta.options || {};
    const match = new RegExp(o.match || '/job/', 'i');
    const words = s => s.replace(/-\d+$/, '').split('-').filter(Boolean)
      .map(x => ({ devops: 'DevOps', mlops: 'MLOps', genai: 'GenAI', llm: 'LLM', llms: 'LLMs' })[x.toLowerCase()]
        || (/^(ai|ml|it|ui|ux|aws|gcp|sql|api|qa|bi|sre)$/i.test(x) ? x.toUpperCase() : x[0].toUpperCase() + x.slice(1))).join(' ');
    rows = (raw.match(/<url>[\s\S]*?<\/url>/g) || raw.match(/<loc>[^<]+<\/loc>/g) || []).map(u => {
      const loc = strip(tag(u, 'loc') || u), parts = loc.replace(/^https?:\/\/[^/]+/, '').split('/');
      return { loc, parts, lastmod: strip(tag(u, 'lastmod')).slice(0, 10) };
    }).filter(x => match.test(x.loc)).map(x => ({ id: x.parts[o.idIndex] || x.loc, title: words(x.parts[o.slugIndex] || ''),
      loc: o.cityIndex ? words(x.parts[o.cityIndex] || '') : (o.city || ''), url: x.loc, desc: '', posted: x.lastmod,
      detailUrl: x.loc }));
  } else if (ats === 'eightfold' && (Array.isArray(d.positions) || (d.data && Array.isArray(d.data.positions)))) {
    // Qualcomm (pcsx) and Netflix (apply v2). No description in the list: Fetch Detail reads it.
    const [host, domain] = String(meta.token).split('|');
    rows = (d.positions || d.data.positions).map(p => ({ id: p.id, title: p.name,
      loc: [].concat(p.locations || p.location || []).join(' / '),
      url: p.canonicalPositionUrl || `https://${host}/careers/job/${p.id}`, desc: strip(p.job_description || ''),
      posted: (p.t_create || p.postedTs) ? new Date((p.t_create || p.postedTs) * 1000).toISOString().slice(0, 10) : '',
      detailUrl: `https://${host}/api/apply/v2/jobs/${p.id}?domain=${domain}` }));
  } else if (ats === 'smartrecruiters' && Array.isArray(d.content)) {
    rows = d.content.map(j => ({ id: j.id, title: j.name,
      loc: [(j.location || {}).city, (j.location || {}).fullLocation].filter(Boolean).join(' '),
      url: `https://jobs.smartrecruiters.com/${meta.token}/${j.id}`, desc: '',
      posted: String(j.releasedDate || '').slice(0, 10), detailUrl: j.ref }));
  }

  for (const r of rows) {
    if (!r.title || !ENG.test(r.title) || NOPE.test(r.title)) continue;
    let region = want.find(w => RX[w] && RX[w].test(r.loc)), city = r.loc;
    // Ashby secondaryLocations / Lever allLocations: ElevenLabs lists London first and Amsterdam as
    // one of a dozen others. The primary location still wins when it is in a wanted region.
    if (!region) for (const l of (r.alt || [])) {
      region = want.find(w => RX[w] && RX[w].test(l));
      if (region) { city = l; break; }
    }
    // A country-filtered Workday search only returns jobs in that country, so an unreadable
    // site code there still means "in our country"; take the employer's own region.
    if (!region && r.countryFiltered) region = (meta.regions || []).find(x => want.includes(x));
    if (!region) continue;
    const key = company + '|' + r.id;                   // searched per term -> same job repeats
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      source: 'ats:' + ats, tier: meta.tier || 'curated', ref: String(r.id || ''),
      title: r.title, company, city, region, country: region === 'amsterdam' ? 'NL' : 'DE',
      remote: region === 'remote',
      postedAt: r.posted, homeoffice: /remote|hybrid/i.test(r.loc + ' ' + r.desc), isAgency: false,
      url: r.url || '', description: (r.desc || '').slice(0, 6000),
      needsDetail: !!r.detailUrl && !r.desc, detailUrl: r.detailUrl || '',
      contactEmail: '',           // ATS apply is employer-key only -> always the fast-path queue
      applyChannel: 'ats'
    }});
  }
}
return out;

