const want = new Set(cfg.regions || []);

// Watchlist employers from Postgres (table `employers`): the companies whose OWN careers site
// runs on SuccessFactors, Workday, SmartRecruiters, Personio... Error rows (table missing,
// DB down) have no `ats` and drop out, so the curated registry still runs on its own.
const rows = $('Load Employers').all().map(i => i.json || {}).filter(r => r.ats && r.token);
const seen = new Set();
const boards = REGISTRY.map(c => ({ ...c, options: c.options || {}, tier: 'curated' }))
  .concat(rows.map(r => ({ ats: String(r.ats).toLowerCase(), token: String(r.token), name: r.name,
    regions: Array.isArray(r.regions) ? r.regions : String(r.regions || '').replace(/[{}]/g, '').split(',').filter(Boolean),
    options: (typeof r.options === 'string' ? JSON.parse(r.options || '{}') : r.options) || {},
    tier: 'watchlist' })))
  .filter(b => { const k = b.ats + '|' + b.token.toLowerCase(); if (seen.has(k)) return false; seen.add(k); return true; })
  .filter(b => b.regions.some(r => want.has(r)));

// Big employers list hundreds of roles, most irrelevant; their feeds are searched per term
// instead of downloaded whole. One request per (employer, term), merged back in Normalize ATS.
const terms = (cfg.employerSearchTerms && cfg.employerSearchTerms.length) ? cfg.employerSearchTerms
  : ['KI', 'AI', 'Machine Learning', 'Software Engineer', 'Softwareentwickler', 'Python'];
const COUNTRY = { berlin: 'de', bayern: 'de', amsterdam: 'nl' };
const enc = encodeURIComponent;
const get = (b, url, term) => ({ ...b, method: 'GET', url, term: term || '' });

const out = [];
for (const b of boards) {
  const t = b.token;
  switch (b.ats) {
    case 'greenhouse': out.push(get(b, `https://boards-api.greenhouse.io/v1/boards/${t}/jobs?content=true`)); break;
    case 'lever':      out.push(get(b, `https://api.lever.co/v0/postings/${t}?mode=json`)); break;
    case 'ashby':      out.push(get(b, `https://api.ashbyhq.com/posting-api/job-board/${t}`)); break;
    case 'recruitee':  out.push(get(b, `https://${t}.recruitee.com/api/offers/`)); break;
    case 'personio':   // token = subdomain, or a full host for the newer *.jobs.personio.com boards
      out.push(get(b, `https://${t.includes('.') ? t : t + '.jobs.personio.de'}/xml?language=${b.options.language || 'de'}`)); break;
    case 'successfactors': { // token = the site's base URL; its public RSS returns ~20 items per query
      // The RSS ignores every location parameter, but location words in the keywords re-rank it:
      // measured on Schaeffler, "Software" gave 0/20 German jobs, "Software DE" gave 14/20.
      const sfx = b.options.keywordSuffix ? ' ' + b.options.keywordSuffix : '';
      for (const term of terms) out.push(get(b, `${t.replace(/\/+$/, '')}/services/rss/job/?locale=${b.options.locale || 'de_DE'}&keywords=${enc(term + sfx)}`, term));
      break;
