      const countries = [...new Set(b.regions.filter(r => want.has(r)).map(r => COUNTRY[r]).filter(Boolean))];
      for (const c of countries) for (const term of terms)
        out.push(get(b, `https://api.smartrecruiters.com/v1/companies/${t}/postings?limit=100&country=${c}&q=${enc(term)}`, term));
      break;
    }
    case 'jibe':       // token = host; Booking.com's public jobs API (iCIMS/Jibe). robots.txt allows /, crawl-delay 5
      out.push(get(b, `https://${t}/api/jobs?location=${enc(b.options.location || 'Amsterdam')}&page=1&limit=100`)); break;
    case 'sitemap':    // token = sitemap URL; job pages are read later by Fetch Detail (schema.org JobPosting)
      out.push(get(b, t)); break;
    case 'eightfold': {      // token = "host|domain|api"; api is "apply" (v2) or "pcsx", per site
      const [host, domain, api] = t.split('|');
      const AREA = { amsterdam: 'Amsterdam', berlin: 'Berlin', bayern: 'Munich' };
      for (const r of b.regions.filter(r => want.has(r) && AREA[r])) out.push(get(b, api === 'pcsx'
        ? `https://${host}/api/pcsx/search?domain=${domain}&query=&location=${enc(AREA[r])}&start=0`
        : `https://${host}/api/apply/v2/jobs?domain=${domain}&start=0&num=100&location=${enc(AREA[r])}`));
      break;
    }
    case 'workday': {        // token = "tenant|wdN|site"; the public CXS endpoint wants a POST
      const [tenant, wd, site] = t.split('|');
      if (!tenant || !wd || !site) break;
      for (const term of terms) out.push({ ...b, method: 'POST', term,
        url: `https://${tenant}.${wd}.myworkdayjobs.com/wday/cxs/${tenant}/${site}/jobs`,
        body: { appliedFacets: b.options.facets || {}, limit: 20, offset: 0, searchText: term } });
      break;
    }
  }
}
return out.map(json => ({ json }));

const cfg = $('Config').first().json;
// Decides whether this run needs to fetch at all. Company key copied from Dedupe & Cap.
const norm = s => String(s || '').toLowerCase().replace(/ß/g, 'ss')
  .normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim();
// One employer, many spellings: the registry says "Nebius", Arbeitnow "Nebius B.V.", the
// Bundesagentur "Nebius GmbH". Without folding legal forms, one-per-company and the history
// check both miss, and the same company gets a second application.
const LEGAL = /\b(gmbh|mbh|ag|se|kg|kgaa|co|ug|ohg|e v|ev|b v|bv|n v|nv|inc|llc|ltd|limited|plc|corp|corporation|sa|sas|sarl|srl|spa|holding|group|gruppe|deutschland|germany|netherlands|nederland|europe)\b/g;
const coKey = s => norm(s).replace(LEGAL, ' ').replace(/\s+/g, ' ').trim() || norm(s);

// Companies already approached (sent, send_failed, applied_manually) are not usable.
const approached = new Set();
for (const r of $('Load History').all()) {
  const h = r.json || {};
  if (h.dedupe_key && h.status !== 'rejected_fit' && h.status !== 'manual') approached.add(coKey(h.company));
}
// One job per company, as Dedupe & Cap will pick.
const seen = new Set();
const usable = [].concat(($('Load Backlog').first().json || {}).backlog || []).filter(r => {
  const co = coKey(r.company);
  if (!(!(cfg.regions || []).length || cfg.regions.includes(r.region))) return false;   // a Bayern backlog row must not stop the fetch
  if (!co || approached.has(co) || seen.has(co)) return false;
  seen.add(co);
  return true;
});
const target = Number(cfg.maxPerRun) || 30;
return [{ json: { backlog: usable.length, target, fetch: usable.length < target } }];

const cfg = $('Config').first().json;
// Instaffo's public board, jobs.instaffo.com. Its /api/ is disallowed in robots.txt, so this reads
// the server-rendered category pages: one per (category, city), 10 jobs per page. Instaffo only
// has city pages for Berlin, München and Nürnberg - none for Augsburg or the Netherlands.
// Measured 2026-10-02: software-entwicklung + data-jobs held all 99 tech jobs in the three cities;
// the narrower machine-learning-engineer, backend and full-stack pages added none.
if (!cfg.useInstaffo) return [];
const CITIES = { berlin: 'berlin', muenchen: 'bayern', nuernberg: 'bayern' };
const cats = (cfg.instaffoCategories && cfg.instaffoCategories.length) ? cfg.instaffoCategories
  : ['software-entwicklung', 'data-jobs'];
// Pages are not sorted by date, so read them all. Past the last page Instaffo returns an empty
// page, not an error. Largest measured: software-entwicklung-berlin, 45 jobs = 5 pages.
const pages = Math.max(1, Math.min(Number(cfg.instaffoPages) || 6, 15));
const out = [];
for (const [city, region] of Object.entries(CITIES)) {
  if (!(cfg.regions || []).includes(region)) continue;
  for (const cat of cats) for (let page = 1; page <= pages; page++)
    out.push({ json: { url: `https://jobs.instaffo.com/de/jobs/${cat}-${city}` + (page > 1 ? `?page=${page}` : ''),
                       city, region } });
}
return out;

const cfg = $('Config').first().json;
// One response per page, in order, errors included - so item i belongs to the i-th page.
const pages = $('Build Instaffo Pages').all();
const cutoff = Date.now() - (cfg.maxDaysOld || 30) * 86400000;

// jobs.instaffo.com is a Next.js app: the job cards travel as React Server Component chunks,
// self.__next_f.push([1,"<JSON-escaped text>"]), each card an object {"job":{uuid, name, postedAt,
// company, locations, ...}}. Decode the chunks, then cut each card out with a string-aware brace scan.
const CHUNK = /self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g;
function cards(html) {
  let s = '';
  for (const m of String(html || '').matchAll(CHUNK)) { try { s += JSON.parse('"' + m[1] + '"'); } catch (e) {} }
  const out = [];
  let i = s.indexOf('{"job":{');
  while (i !== -1) {
    let depth = 0, str = false, esc = false, j = i;
    for (; j < s.length; j++) {
      const ch = s[j];
      if (str) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') str = false; }
      else if (ch === '"') str = true;
      else if (ch === '{') depth++;
      else if (ch === '}' && --depth === 0) break;
    }
    try { const job = JSON.parse(s.slice(i, j + 1)).job; if (job && job.name) out.push(job); } catch (e) {}
    i = s.indexOf('{"job":{', j + 1);
  }
  return out;
}

const seen = new Set();
const out = [];
$input.all().forEach((item, i) => {
  const p = (pages[i] || {}).json || {};
  for (const job of cards((item.json || {}).data || (item.json || {}).body)) {
    const key = job.uuid || job.slug;
    if (seen.has(key)) continue;              // one job sits in several category pages
    seen.add(key);
    // postedAt is the date the card shows ("vor 3 Monaten") and the job page's datePosted.
    const ts = Date.parse(job.postedAt || job.activatedAt || '');
    if (ts && ts < cutoff) continue;
    const company = (job.company || {}).name || '';
    const cities = (job.locations || []).map(l => l.cityDe || l.cityEn).filter(Boolean);
    out.push({ json: {
      source: 'instaffo', tier: 'search', ref: String(job.slug || job.uuid || ''),
      title: job.name || '', company,
      city: cities.join(', ') || p.city || '', region: p.region, country: 'DE',
      postedAt: ts ? new Date(ts).toISOString().slice(0, 10) : '',
      homeoffice: !!(job.remote || job.hybrid),
      isAgency: /recruit|staffing|personal|zeitarbeit|uberlassung/i.test(company),
      url: job.url || '',
      // The card has no description: Fetch Detail reads it from the job page's JSON-LD.
      detailUrl: job.url || '', needsDetail: !!job.url, description: '',
      contactEmail: '', applyChannel: 'link'
    }});
  }
});
return out;

const cfg = $('Config').first().json;
// Workable's public job search (jobs.workable.com, the board behind its "Find jobs" page): the
// international scale-ups that run their careers page on Workable - Enjins, Modash, Soda Data,
// Keylane. Keyless JSON, 20 jobs a page; Fetch Workable follows nextPageToken.
// Measured 2026-10-13: "Amsterdam" already returns Utrecht and Haarlem jobs, Rotterdam adds Den Haag.
// Search centres per region. Measured 2026-11-09: "Berlin" returns ~60 jobs in 30 days, nearly all English.
// remote: Germany-wide with Workable's workplace=remote filter (measured: 49 jobs, all remote).
const CENTRES = { amsterdam: [].concat(cfg.nlLocations || 'Amsterdam'), berlin: ['Berlin'], bayern: ['Munich', 'Nuremberg'],
  remote: ['Germany|remote'] };
const want = (cfg.regions || []).filter(r => CENTRES[r]);
if (!cfg.useWorkable || !want.length) return [];
const locations = want.flatMap(r => CENTRES[r]);
const terms = cfg.workableTerms || ['AI', 'machine learning', 'data scientist', 'engineer', 'developer'];
const days = Math.max(1, Number(cfg.maxDaysOld) || 30);
const out = [];
for (const query of terms) for (const centre of locations) {
  const [location, workplace] = centre.split('|');
  out.push({ json: { query, location, url: 'https://jobs.workable.com/api/v1/jobs?query=' + encodeURIComponent(query)
    + '&location=' + encodeURIComponent(location) + '&day_range=' + days + (workplace ? '&workplace=' + workplace : '') } });
}
return out;

const cfg = $('Config').first().json;
// One item per page. Overlapping terms and centres repeat jobs, so dedupe by id. Each job carries an
// ISO language code - nearly all English, which is the point of this source.
const NL = /\b(amsterdam|amstelveen|diemen|duivendrecht|badhoevedorp|schiphol|hoofddorp|haarlem|zaandam|purmerend|weesp|aalsmeer|uithoorn|almere|hilversum|bussum|naarden|huizen|amersfoort|utrecht|nieuwegein|zeist|houten|bunnik|woerden|maarssen|leiden|katwijk|noordwijk|delft|den haag|the hague|gravenhage|rijswijk|zoetermeer|leidschendam|voorburg|rotterdam|capelle|schiedam|gouda|eindhoven|noord-holland|zuid-holland|north holland|south holland|netherlands|nederland)\b/i;
const strip = h => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
const BERLIN = /\b(berlin|potsdam|teltow|kleinmachnow|sch[oö]nefeld|hennigsdorf|falkensee|oranienburg|bernau|k[oö]nigs wusterhausen|ludwigsfelde)\b/i;
const BAYERN = /\b(m[uü]nchen|munich|n[uü]rnberg|nuremberg|bayern|bavaria|augsburg|erlangen|f[uü]rth|herzogenaurach|forchheim|ingolstadt|regensburg|w[uü]rzburg|bamberg|garching|unterf[oö]hring|unterschlei[sß]heim|ismaning|oberpfaffenhofen|we[sß]ling|planegg|martinsried|starnberg|freising|rosenheim|landshut|passau|bayreuth|aschaffenburg|schweinfurt)\b/i;
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  for (const j of (item.json.jobs || [])) {
    if (!j.id || seen.has(j.id)) continue;
    seen.add(j.id);
    const L = j.location || {};
    const where = [L.city, L.subregion, L.countryName].filter(Boolean).join(', ');
    // The search radius is generous: keep the wanted areas only.
    const region = (cfg.regions || []).includes('amsterdam') && NL.test(where) ? 'amsterdam'
      : (cfg.regions || []).includes('berlin') && BERLIN.test(where) ? 'berlin'
      : (cfg.regions || []).includes('bayern') && BAYERN.test(where) ? 'bayern'
      // Elsewhere in Germany: only a remote job.
      : (cfg.regions || []).includes('remote') && /remote/i.test(j.workplace || '') && /germany|deutschland/i.test(L.countryName || '') ? 'remote' : '';
    if (!region) continue;
    if (region === 'amsterdam' && cfg.skipDutchRequired !== false && j.language === 'nl') continue;
    const co = (j.company || {}).title || '';
    out.push({ json: {
      source: 'workable', tier: 'search', ref: String(j.id), title: j.title || '', company: co,
      city: where, region, country: region === 'amsterdam' ? 'NL' : 'DE',
      postedAt: String(j.created || '').slice(0, 10),
      homeoffice: /remote|hybrid/i.test(j.workplace || ''),
      isAgency: /recruit|staffing|uitzend|detacher|werving|headhunt|talent solutions/i.test(co),
      url: j.url || '', description: strip([j.description, j.requirementsSection].filter(Boolean).join(' ')).slice(0, 6000),
      contactEmail: '', applyChannel: 'link'
    }});
  }
}
return out;

const cfg = $('Config').first().json;
// ONE spreadsheet, rebuilt every run from the database: every open apply-yourself job (status manual
// or send_failed, last 2 x maxDaysOld days), priority region first, then fit. This run's roles add
// the angle, gaps and LinkedIn note, which the database does not store. Mark a job as done with
//   UPDATE job_applications SET status = 'applied_manually' WHERE url = '<link>';
// and it leaves the list on the next run.
const db = $input.all().map(i => i.json).filter(r => r && r.dedupe_key);
const run = new Map($('Record Outcome').all().map(i => i.json).filter(j => j.dedupeKey).map(j => [j.dedupeKey, j]));
const today = new Date().toISOString().slice(0, 10);
// The database is the list. If it could not be read, fall back to this run's roles.
const src = db.length ? db : [...run.values()].filter(j => ['manual', 'queued', 'dry_run', 'send_failed'].includes(j.status))
  .map(j => ({ dedupe_key: j.dedupeKey, company: j.company, title: j.title, city: j.city, region: j.region, url: j.url,
    fit: j.fit, score_reason: j.scoreReason, letter: j.letter, status: j.status, added: today }));
const pri = r => (cfg.priorityRegion && r.region === cfg.priorityRegion) ? 1 : 0;
// Only the regions in Config: older rows from a region since switched off stay out of the list.
for (let k = src.length - 1; k >= 0; k--) if ((cfg.regions || []).length && !cfg.regions.includes(src[k].region)) src.splice(k, 1);
src.sort((a, b) => (pri(b) - pri(a)) || ((b.fit ?? -1) - (a.fit ?? -1)));
const rows = src.map((r, i) => {
  const j = run.get(r.dedupe_key) || {};
  return {
    '#': i + 1,
    Added: r.added || '',
    New: r.added === today ? 'new' : '',
    Region: r.region || '',
    Company: r.company || '',
    Role: r.title || '',
    City: r.city || '',
    Fit: r.fit ?? '',
    Status: r.status === 'send_failed' ? 'email failed - apply by hand' : (r.letter ? 'letter ready' : 'no letter yet'),
    Link: r.url || '',
    Email: r.contact_email || j.publishedEmail || '',
    'Why you fit': j.angle || r.score_reason || '',
    Gaps: (j.missing || []).join('; '),
    Subject: j.subject || '',
    'Cover letter': r.letter || '',
    'LinkedIn note': j.linkedinNote || ''
  };
});
// Always one row: Export to Excel feeds Write Export and the digest.
if (!rows.length) rows.push({ '#': '', Added: '', New: '', Region: '', Company: '(no open apply-yourself jobs)', Role: '',
  City: '', Fit: '', Status: '', Link: '', Email: '', 'Why you fit': '', Gaps: '', Subject: '', 'Cover letter': '', 'LinkedIn note': '' });
return rows.map(json => ({ json }));

const cfg = $('Config').first().json;
// "Look again until enough." The pool holds the best-ranked roles. If fewer than emailTarget of them
// can be emailed, work down the reserve (Dedupe & Cap): priority region first, then relevance, so the
// title bar drops one step at a time and only as far as this run needs. Bundesagentur ads are fetched
// 5 at a time; the hunt stops as soon as the target is met. Unused reserve is not recorded, so it is
// considered again next run.
// Same rule as Filter Relevant. Sitemap/Workday/Eightfold ads only arrive with the detail fetch, after
// Filter Relevant's language gate, so NL ones are checked again here.
const NLW = /\b(het|een|van|voor|met|jij|jouw|wij|onze|bij|naar|zijn|wordt|ervaring|kennis|werkzaamheden|functie|vacature|ook|niet|wat|hoe|heb|hebt|je|binnen|zoeken|bieden)\b/gi;
const ENW = /\b(the|and|you|with|for|our|your|will|are|is|of|to|we|this|that|team|experience)\b/gi;
function needsDutch(text) {
  const d = String(text || '').slice(0, 8000);
  const nl = (d.slice(0, 4000).match(NLW) || []).length, en = (d.slice(0, 4000).match(ENW) || []).length;
  if (nl + en >= 15 && nl > en) return true;                       // written in Dutch
  const re = /\bdutch\b/gi;
  let m;
  while ((m = re.exec(d))) {
    const s = d.slice(Math.max(0, m.index - 120), m.index).split(/[.!?;\u2022\u2705\u274c]\s/).pop()
      + d.slice(m.index, m.index + 120).split(/[.!?;\u2022\u2705\u274c]\s/)[0];
    // About the language, not "Dutch GAAP" or "Dutch labour law".
    if (!/\b(fluen\w*|native|proficien\w*|speak\w*|spoken|written|command)\b/i.test(s)) continue;
    if (/\b(plus|bonus|advantage\w*|prefer\w*|nice|asset|beneficial|welcome|useful|helpful|optional|ideally|learn\w*|and\/or|(?:english|german) or dutch|not (?:required|essential|necessary|needed|mandatory|a must)|or (?:another|danish|french|german|english))\b/i.test(s)) continue;
    return true;
  }
  return false;
}
const all = $input.all().map(i => i.json)
  .filter(j => !(j.country === 'NL' && cfg.skipDutchRequired !== false && j.description && needsDutch(j.title + '. ' + j.description)));
const pool = all.filter(j => !j.reserve && !j.noCandidates);
const reserve = all.filter(j => j.reserve);
const target = Math.max(0, Number(cfg.emailTarget ?? cfg.maxPerRun ?? 8));
// Collect more addresses than mails wanted: a found job can still fall under minFitScoreEmail.
const collect = Math.ceil(target * Math.max(1, Number(cfg.emailHuntFactor ?? 1)));
const inPool = pool.filter(j => j.contactEmail).length;
const http = (typeof helpers !== 'undefined' && helpers && helpers.httpRequest) ? helpers : this.helpers;
const b64 = s => (typeof Buffer !== 'undefined' ? Buffer.from(String(s)).toString('base64') : btoa(String(s)));

// The Bundesagentur address rule, copied from Extract Contact.
const RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24}/g;
const BLOCK = /(noreply|no-reply|donotreply|postmaster|example\.|@arbeitsagentur\.|\.png|\.jpg)/i;
const TLD = '(?:com|de|net|org|eu|io|ai|nl|at|ch|info|jobs|gmbh|group|tech)';
const baEmail = desc => {
  for (const raw of (String(desc).match(RE) || [])) {
    let e = raw.replace(new RegExp('^([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+?\\.' + TLD + ')[A-ZÄÖÜ].*$'), '$1');
    e = e.replace(/[.,;:)\]]+$/, '').toLowerCase();
    if (BLOCK.test(e)) continue;
    return e;
  }
  return '';
};

const found = [];
let checked = 0, failed = 0;
for (let i = 0; i < reserve.length && inPool + found.length < collect; i += 5) {
  const batch = reserve.slice(i, i + 5);
  const res = await Promise.all(batch.map(async j => {
    if (j.contactEmail) return { j, email: j.contactEmail, desc: j.description };
    if (j.source !== 'bundesagentur' || !j.ref) return { j, email: '' };
    try {
      const d = await http.httpRequest({ method: 'GET', json: true, timeout: 20000,
        url: 'https://rest.arbeitsagentur.de/jobboerse/jobsuche-service/pc/v4/jobdetails/' + b64(j.ref),
        headers: { 'X-API-Key': 'jobboerse-jobsuche', Accept: 'application/json' } });
      const desc = String((d && d.stellenangebotsBeschreibung) || '');
      return { j, email: baEmail(desc), desc };
    } catch (e) { failed++; return { j, email: '' }; }
  }));
  checked += batch.length;
  for (const r of res) if (r.email && inPool + found.length < collect) found.push({ ...r.j, reserve: false, fromHunt: true,
    contactEmail: r.email, applyChannel: 'email', needsDetail: false,
    description: String(r.desc || r.j.description || '').slice(0, 6000) });
}

const huntStats = { target, collect, inPool, reserve: reserve.length, checked, found: found.length, failed };
const out = pool.concat(found);
if (!out.length) return [{ json: { noCandidates: true, huntStats } }];
out[0] = { ...out[0], huntStats };
return out.map(json => ({ json }));

const cfg = $('Config').first().json;
// Feeds: one text response per request, read by Normalize Feeds.
//   Jobicy: remote jobs open to Germany, and to Europe (public API; no key, attribution asked).
//   service.bund.de: the federal job portal's RSS (latest 500, all of Germany). robots.txt blocks its search
//   pages, not this feed. Only Bavaria/Berlin postcodes are kept - public-sector jobs are rarely remote.
//   englishjobsearch.nl: a search engine for English-language jobs in the Netherlands. It aggregates other
//   boards, so it shows employers this workflow has no feed for (measured 2026-11-16: 46 result pages gave
//   384 fresh ads at 286 employers, 227 of them pass Filter Relevant). robots.txt allows the result pages.
//   It disallows /clickout/ (the job links - stored for you to click, never fetched) and ?posted= (not used).
//   One request per result page, 20 jobs a page, best title matches first. A search is "area/query/pages".
//   englishjobs.de: the same site for Germany (same operator and robots.txt). englishJobsSearchesDE, areas "bayern" and
//   "berlin" (a Bavarian city slug such as "muenchen" counts as bayern). Measured 2026-11-18: 50 pages gave 167 roles
//   in Bayern and Berlin that pass the title rules, 112 of them at 79 employers the workflow had never read or listed.
//   DevITjobs.nl: one JSON list of Dutch IT jobs; only its English ads are kept.
const want = cfg.regions || [];
const out = [];
if (cfg.useJobicy && want.includes('remote')) for (const geo of ['germany', 'europe'])
  out.push({ json: { feed: 'jobicy', url: `https://jobicy.com/api/v2/remote-jobs?count=100&geo=${geo}` } });
if (cfg.useBundJobs && (want.includes('bayern') || want.includes('berlin')))
  out.push({ json: { feed: 'bund', url: 'https://www.service.bund.de/Content/Globals/Functions/RSSFeed/RSSGenerator_Stellen.xml' } });
if (cfg.useEnglishJobs && want.includes('amsterdam')) for (const s of cfg.englishJobsSearches || []) {
  const [area, query, pages] = String(s).trim().split('/');
  if (!area || !query) continue;
  const n = Math.max(1, Math.min(Number(pages) || 1, 15));
  for (let p = 1; p <= n; p++) out.push({ json: { feed: 'englishjobs', site: 'nl', area, query, page: p,
    url: `https://englishjobsearch.nl/in/${encodeURIComponent(area)}/${encodeURIComponent(query)}` + (p > 1 ? `?page=${p}` : '') } });
}
const DE_AREA = a => /^(berlin|potsdam|brandenburg)$/i.test(a) ? 'berlin' : 'bayern';
if (cfg.useEnglishJobs) for (const s of cfg.englishJobsSearchesDE || []) {
  const [area, query, pages] = String(s).trim().split('/');
  if (!area || !query || !want.includes(DE_AREA(area))) continue;
  const n = Math.max(1, Math.min(Number(pages) || 1, 15));
  for (let p = 1; p <= n; p++) out.push({ json: { feed: 'englishjobs', site: 'de', area, query, page: p,
    url: `https://englishjobs.de/in/${encodeURIComponent(area)}/${encodeURIComponent(query)}` + (p > 1 ? `?page=${p}` : '') } });
}
if (cfg.useDevITjobs && want.includes('amsterdam'))
  out.push({ json: { feed: 'devitjobs', url: 'https://devitjobs.nl/api/jobsLight' } });
return out;

const cfg = $('Config').first().json;
// One text response per request, in order (Fetch Feed answers as text, errors included).
const reqs = $('Build Feed Requests').all();
const want = cfg.regions || [];
const strip = h => String(h || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d))
  .replace(/\s+/g, ' ').trim();
const tag = (x, t) => { const m = String(x).match(new RegExp('<' + t + '>([\\s\\S]*?)</' + t + '>')); return m ? m[1] : ''; };
const ELIG = /\b(germany|deutschland|dach|europe|eu|emea|cet)\b/i;
const cutoff = Date.now() - (Number(cfg.maxDaysOld) || 30) * 86400000;
// The Amsterdam area, as in Normalize ATS.
const NL = /\b(amsterdam|amstelveen|diemen|duivendrecht|badhoevedorp|schiphol|hoofddorp|haarlem|zaandam|purmerend|weesp|aalsmeer|uithoorn|almere|hilversum|bussum|naarden|huizen|amersfoort|utrecht|nieuwegein|zeist|houten|bunnik|woerden|maarssen|leiden|katwijk|noordwijk|delft|den haag|the hague|gravenhage|rijswijk|zoetermeer|leidschendam|voorburg|rotterdam|capelle|schiedam|gouda|eindhoven|noord-holland|zuid-holland|north holland|south holland|netherlands|nederland)\b/i;
// englishjobsearch.nl shows who posted the ad, and that is often not the employer. Sites that repost other
// people's ads are dropped: the employer is unknown, so the job can neither be deduplicated nor judged.
// Agencies are flagged, and Filter Relevant drops them while excludeAgencies is on. Both lists come from the
// 765 ads harvested on 2026-11-16; they are a best effort, not complete.
const EJ_REPOST = /^(jobgether|fde times|arbeitnow|vacaturebank|nationale vacaturebank|efinancialcareers|graduate|devconnectplatform|remote ?work|confidential|software|relocate\.me|startup atlas|deepcamp|rust ui|vuetoronto|larabench|patrickbeek\.com|present of ai|mbianchi|ainurhq|y-axis|placements24|xpertdirect|jobleads|stealth startup|indeed|linkedin|glassdoor|whatjobs|jooble|adzuna|tideri|talent\.com|careerjet|monsterboard|werkzoeken)$/i;
const EJ_AGENCY = /recruit|staffing|staffice|stafide|talent|headhunt|\bsearch\b|resourc|professionals|associates|personnel|uitzend|detacher|werving|hamilton barnes|harnham|russell tobin|ampstek|wypoon|gazelle global|levy global|oakwell hampton|doghouse|\bhays\b|michael page|robert walters|oliver james|huxley|computer futures|\byacht\b|brunel|randstad|start people|adecco|manpower|experis|us3 consulting|geeksoft|testq|next ventures|morgan black|la fosse|european tech|microtech global|belmont lavan|ventula|foxtek|spilberg|thewhiteam|thegiglab|salve\.|^salt$|^yer$/i;
// englishjobs.de (the same site for Germany): the cities as in Normalize ATS and Normalize Workable, plus suburbs seen
// in its ads (Ottobrunn, Neubiberg, Manching, ...).
const DE_BY = /\b(m[uü]nchen|munich|n[uü]rnberg|nuremberg|bayern|bavaria|augsburg|erlangen|f[uü]rth|herzogenaurach|forchheim|ingolstadt|regensburg|w[uü]rzburg|bamberg|garching|unterf[oö]hring|unterschlei[sß]heim|ismaning|oberpfaffenhofen|we[sß]ling|planegg|martinsried|starnberg|freising|rosenheim|landshut|passau|bayreuth|aschaffenburg|schweinfurt|ottobrunn|neubiberg|taufkirchen|unterhaching|gr[uü]nwald|pullach|gilching|germering|dachau|erding|haar|aschheim|feldkirchen|manching|kaufbeuren|kempten|memmingen|coburg|amberg|straubing|deggendorf|neu-ulm)\b/i;
const DE_BE = /\b(berlin|potsdam|teltow|kleinmachnow|sch[oö]nefeld|hennigsdorf|falkensee|oranienburg|bernau|k[oö]nigs wusterhausen|ludwigsfelde)\b/i;
const DE_FULLREMOTE = /(100\s?%\s?remote|fully remote|full[- ]remote|remote[- ]first|remote[- ]only|vollst[aä]ndig remote|ortsunabh[aä]ngig|remote (within|in|across) germany|remote,? germany\b|work from anywhere in (germany|europe))/i;
const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const out = [];
const seen = new Set();
$input.all().forEach((item, i) => {
  const req = (reqs[i] || {}).json || {};
  const feed = req.feed;
  const raw = typeof item.json.data === 'string' ? item.json.data : '';
  if (feed === 'jobicy') {
    let d = {}; try { d = JSON.parse(raw); } catch (e) {}
    for (const j of d.jobs || []) {
      const key = 'jobicy|' + j.id;
      if (seen.has(key) || !ELIG.test(String(j.jobGeo || ''))) continue;   // e.g. "USA, Germany" counts, "USA" alone does not
      if (j.pubDate && new Date(j.pubDate).getTime() < cutoff) continue;
      seen.add(key);
      out.push({ json: { source: 'jobicy', tier: 'search', ref: String(j.id), title: strip(j.jobTitle), company: strip(j.companyName),
        city: 'Remote (' + strip(j.jobGeo) + ')', region: 'remote', country: 'DE', remote: true,
        postedAt: String(j.pubDate || '').slice(0, 10), homeoffice: true,
        isAgency: /recruit|staffing|talent|hiring/i.test(j.companyName || ''),
        url: j.url || '', description: strip(j.jobDescription || j.jobExcerpt).slice(0, 6000), contactEmail: '', applyChannel: 'link' } });
    }
  } else if (feed === 'bund') {
    for (const it of String(raw).match(/<item>[\s\S]*?<\/item>/g) || []) {
      const desc = tag(it, 'description');
      const plz = Number((strip(desc).match(/Ort:\s*(\d{5})/) || [])[1]);
      const region = (plz >= 80000 && plz <= 87999) || (plz >= 90000 && plz <= 97999) ? 'bayern'
        : plz >= 10000 && plz <= 14199 ? 'berlin' : '';          // 14xxx includes Potsdam
      if (!region || !want.includes(region)) continue;
      const link = strip(tag(it, 'guid') || tag(it, 'link'));
      if (seen.has(link)) continue;
      seen.add(link);
      const posted = new Date(strip(tag(it, 'pubDate')));
      out.push({ json: { source: 'bund', tier: 'search', ref: link, title: strip(tag(it, 'title')),
        company: (strip(desc).match(/Arbeitgeber:\s*(.*?)\s*Ort:/) || [])[1] || '',
        city: (strip(desc).match(/Ort:\s*\d{5}\s*(.*?)\s*(Bewerbungsfrist|$)/) || [])[1] || '', region, country: 'DE',
        postedAt: isNaN(posted) ? '' : posted.toISOString().slice(0, 10), homeoffice: false, isAgency: false,
        url: link, description: strip(desc).slice(0, 2000), contactEmail: '', applyChannel: 'link' } });
    }
  } else if (feed === 'englishjobs') {
    // One result page. Each card: id, title, then a list of company / city / date / flags, a text extract,
    // and the job link (a signed /clickout/ redirect to the original ad).
    for (const c of raw.split('<!-- result -->').slice(1)) {
      const id = (c.match(/<div id="([0-9a-f]{8,})" class="job/) || [])[1];
      // The site wraps search hits in <em>: remove the tags without leaving spaces behind.
      const title = strip(((c.match(/<h3[^>]*itemprop="title"[^>]*>([\s\S]*?)<\/h3>/) || [])[1] || '').replace(/<\/?em>/g, ''));
      const li = [...c.matchAll(/<li class="flex text-sm[^"]*">([\s\S]*?)<\/li>/g)].map(m => strip(m[1].replace(/<svg[\s\S]*?<\/svg>/g, '')));
      const href = (c.match(/href="(\/clickout\/[^"]+)"/) || [])[1];
      const de = req.site === 'de', key = 'ej|' + (de ? 'de|' : '') + id;
      if (!id || !title || !href || li.length < 2 || seen.has(key)) continue;
      const company = li[0].replace(/^\d+\s+/, '').trim();          // "0039 eBay Intl Management BV"
      const city = li[1];
      if (!company || EJ_REPOST.test(company)) continue;
      const extract = strip(((c.match(/<div class="mr-4 flex-1[^"]*">([\s\S]*?)<\/div>/) || [])[1] || '').replace(/<\/?em>/g, ''));
      // Netherlands: a province search also returns towns far from the cities - keep the Amsterdam area only.
      // Germany (englishjobs.de): Bayern or Berlin by the city; anywhere else only when the title or the extract says
      // fully remote (measured 2026-11-18: 1 such ad in 598 - the site's "remote work" tag alone is not evidence).
      const region = !de ? ((req.area === 'amsterdam' || NL.test(city)) ? 'amsterdam' : '')
        : DE_BY.test(city) ? 'bayern' : DE_BE.test(city) ? 'berlin' : DE_FULLREMOTE.test(title + ' ' + extract) ? 'remote' : '';
      if (!region || !want.includes(region)) continue;
      let postedAt = '';
      const md = li.slice(2).map(v => v.match(/^([A-Z][a-z]+) (\d{1,2})$/)).find(m => m && MONTHS.includes(m[1].toLowerCase()));
      if (md) {                                                      // "November 11", no year
        const mo = MONTHS.indexOf(md[1].toLowerCase()), y = new Date().getUTCFullYear();
        let t = Date.UTC(y, mo, Number(md[2]));
        if (t > Date.now() + 86400000) t = Date.UTC(y - 1, mo, Number(md[2]));
        if (t < cutoff) continue;
        postedAt = new Date(t).toISOString().slice(0, 10);
      }
      const flags = li.slice(2).filter(v => !(md && v === md[0]));  // "remote work", "visa sponsorship", ...
      seen.add(key);
      out.push({ json: { source: 'englishjobs', tier: 'search', ref: id, title, company, city, region, country: de ? 'DE' : 'NL',
        postedAt, homeoffice: flags.some(f => /remote/i.test(f)) || /\b(remote|hybrid)\b/i.test(extract),
        isAgency: EJ_AGENCY.test(company),
        url: (de ? 'https://englishjobs.de' : 'https://englishjobsearch.nl') + href.replace(/&amp;/g, '&'),
        description: (extract + (flags.length ? ' [' + flags.join(', ') + ']' : '')).slice(0, 2000), contactEmail: '', applyChannel: 'link' } });
    }
  } else if (feed === 'devitjobs') {
    let d = []; try { d = JSON.parse(raw); } catch (e) {}
    for (const j of Array.isArray(d) ? d : []) {
      if (!j || j.language !== 'English' || j.isPaused || !j.jobUrl || seen.has('dij|' + j._id)) continue;
      const city = [j.actualCity, String(j.cityCategory || '').replace(/-/g, ' ')].filter(Boolean).join(', ');
      if (!NL.test(city)) continue;
      const t = j.activeFrom ? new Date(j.activeFrom).getTime() : 0;
      if (t && t < cutoff) continue;
      seen.add('dij|' + j._id);
      const pay = j.annualSalaryFrom ? ` Salary EUR ${j.annualSalaryFrom}-${j.annualSalaryTo || j.annualSalaryFrom} a year.` : '';
      // The list has no ad text: describe the job from its fields, so the scorer sees the stack and level.
      out.push({ json: { source: 'devitjobs', tier: 'search', ref: String(j._id), title: strip(j.name), company: strip(j.company),
        city, region: 'amsterdam', country: 'NL', postedAt: t ? new Date(t).toISOString().slice(0, 10) : '',
        homeoffice: /remote|hybrid/i.test(j.workplace || ''), isAgency: /recruit|staffing|talent|detacher|uitzend/i.test(j.company || ''),
        url: 'https://devitjobs.nl/jobs/' + j.jobUrl,
        description: `${strip(j.name)} at ${strip(j.company)} (${j.companyType || 'company'}, ${j.companySize || '?'} people). `
          + `Level: ${j.expLevel || '?'}. ${j.jobType || ''}, ${j.workplace || ''}. Main stack: ${j.techCategory || '?'}. `
          + `Technologies: ${(j.technologies || []).join(', ')}.${pay} Ad language: English.`,
        contactEmail: '', applyChannel: 'link' } });
    }
  }
});
return out;
